DECLARE
 specs jsonb := $pv_results_payload$[{"lesson":"pv01-01","module":"s02-m01","intro":"Ще избереш задача, за която видеото действително може да помогне. Ще отделяш наблюдаван проблем от предположение и ще записваш началното състояние, преди да обещаваш промяна.","objective":{"body":"Ще избереш задача, за която видеото действително може да помогне. Ще отделяш наблюдаван проблем от предположение и ще записваш началното състояние, преди да обещаваш промяна.","deliverable":"В учебната папка на пекарна „Зърно“ избери един въпрос, на който 25-секунден клип може да отговори. Запиши какво знаеш от условията и какво не знаеш за бъдещите поръчки.","check":"Посочени са проблем, зрител, проверен факт и неизвестно. „Да обясним какво има в кутията и как се получава“ е изпълнима цел; „да удвоим продажбите“ не е доказан резултат."},"note":{"body":"В учебната папка на пекарна „Зърно“ избери един въпрос, на който 25-секунден клип може да отговори. Запиши какво знаеш от условията и какво не знаеш за бъдещите поръчки.\n\nСамопроверка: Посочени са проблем, зрител, проверен факт и неизвестно. „Да обясним какво има в кутията и как се получава“ е изпълнима цел; „да удвоим продажбите“ не е доказан резултат.\n\nГраница: Ако проектът включва реални клиенти, непълнолетни, здравни данни или частни съобщения, първо извади личните данни от учебния пример и уреди разрешенията. Работи с измислени или обобщени стойности, когато няма основание да показваш истинските.\n\nРаботна карта за наблюдението: точни думи/действие; източник и дата; канал и период; брой случаи; извод; неизвестно; следващият тест. Така отделяш факт от тълкуване и можеш да проследиш защо темата е избрана.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да избереш един реален проект и да опишеш какво знаеш и какво още трябва да провериш. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Ако проектът включва реални клиенти, непълнолетни, здравни данни или частни съобщения, първо извади личните данни от учебния пример и уреди разрешенията. Работи с измислени или обобщени стойности, когато няма основание да показваш истинските.\n\nРаботна карта за наблюдението: точни думи/действие; източник и дата; канал и период; брой случаи; извод; неизвестно; следващият тест. Така отделяш факт от тълкуване и можеш да проследиш защо темата е избрана.\n\nКарта за работа — Избери реален проект и запиши началната точка\n1. Избери изпълним проект с достъп до реален зрител и разрешение за снимане.\n2. Назови едно затруднение, което вече си наблюдавал; отдели цитат или действие от собственото си тълкуване.\n3. Запиши изходната метрика, източника и периода; ако липсват, отбележи ги като неизвестни.\n4. Опиши ограниченията: време, място, хора, техника, права и какво няма да обещаваш.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv01-02","module":"s02-m01","intro":"Ще описваш зрителя през ситуацията му: какво се опитва да направи, какво го затруднява и къде гледа. Така ще избираш информация, която му е нужна, вместо да гадаеш по възраст и професия.","objective":{"body":"Ще описваш зрителя през ситуацията му: какво се опитва да направи, какво го затруднява и къде гледа. Така ще избираш информация, която му е нужна, вместо да гадаеш по възраст и професия.","deliverable":"Прочети трите учебни реакции. Избери за кого подготвяш клипа: човек, който организира закуска за шестима, а не „всички, които обичат тестени изделия“.","check":"Описани са конкретна задача и пречка. Репликата „Не разбрах дали доставяте“ подкрепя нужда от ясно условие за получаване, не извод за характера на човека."},"note":{"body":"Прочети трите учебни реакции. Избери за кого подготвяш клипа: човек, който организира закуска за шестима, а не „всички, които обичат тестени изделия“.\n\nСамопроверка: Описани са конкретна задача и пречка. Репликата „Не разбрах дали доставяте“ подкрепя нужда от ясно условие за получаване, не извод за характера на човека.\n\nГраница: Не използвай измислена „персона“ като заместител на интервю. Тя е работна хипотеза за сценария; промени я, когато наблюденията от истински разговори противоречат.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да опишеш конкретен зрител чрез ситуация, нужда и контекст на гледане. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Не използвай измислена „персона“ като заместител на интервю. Тя е работна хипотеза за сценария; промени я, когато наблюденията от истински разговори противоречат.\n\nКарта за работа — Определи за кого е видеото и кога ще го гледа\n1. Избери конкретен момент, в който зрителят среща проблема.\n2. Назови неговата задача с глагол: избере, сравни, разбере, провери или направи.\n3. Отбележи предишния опит, главната пречка и какво би било достатъчно полезно.\n4. Съобрази формат и звук с мястото, където човекът вероятно гледа.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv01-03","module":"s02-m01","intro":"Ще проверяваш как човек решава задачата си сега и къде новото предложение може да му помогне. Сравнението ще включва усилие, време и условия, не само цена.","objective":{"body":"Ще проверяваш как човек решава задачата си сега и къде новото предложение може да му помогне. Сравнението ще включва усилие, време и условия, не само цена.","deliverable":"Сравни три начина за закуска: покупка на място, предварително запитване и доставка от друг търговец. Не добавяй доставка към нашата пекарна, когато тя не я предлага.","check":"За всяка възможност има известно условие и поне едно неизвестно. Изборът не превръща три учебни реакции в представително пазарно проучване."},"note":{"body":"Сравни три начина за закуска: покупка на място, предварително запитване и доставка от друг търговец. Не добавяй доставка към нашата пекарна, когато тя не я предлага.\n\nСамопроверка: За всяка възможност има известно условие и поне едно неизвестно. Изборът не превръща три учебни реакции в представително пазарно проучване.\n\nГраница: Малката извадка е подходяща за намиране на въпроси, но не и за точна оценка на размера на пазара. Прикрепи изводите към периода и канала, от който идват.\n\nКогато два сигнала си противоречат, провери дали са от еднакъв период, канал и етап на решение. Запази и двете наблюдения; не избирай само това, което подкрепя първоначалната идея.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да събереш наблюдения от реални ситуации, преди да избираш тема и послание. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Малката извадка е подходяща за намиране на въпроси, но не и за точна оценка на размера на пазара. Прикрепи изводите към периода и канала, от който идват.\n\nКогато два сигнала си противоречат, провери дали са от еднакъв период, канал и етап на решение. Запази и двете наблюдения; не избирай само това, което подкрепя първоначалната идея.\n\nКарта за работа — Проучи как хората решават проблема си сега\n1. Събери реални въпроси от поне два различни източника.\n2. Запиши точните думи и датата; махни имена и лични детайли.\n3. Групирай повтарящите се затруднения, без да добавяш мотив, който не си чул.\n4. Отдели доказаното, вероятното и неизвестното; избери тема само след това.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv01-04","module":"s02-m01","intro":"Ще различаваш въпрос, който събира информация, от въпрос, който търси одобрение. Ще можеш да отделиш точните думи на човека от собственото си обяснение за тях.","objective":{"body":"Ще различаваш въпрос, който събира информация, от въпрос, който търси одобрение. Ще можеш да отделиш точните думи на човека от собственото си обяснение за тях.","deliverable":"Сравни „Нали кутията би ти спестила време?“ с „Как организира последната обща закуска?“. Избери неутралния въпрос и отдели факт, тълкуване и следваща проверка.","check":"Въпросът не предлага желания отговор. „Писа за доставка“ е наблюдение; „ще купи веднага“ остава предположение."},"note":{"body":"Сравни „Нали кутията би ти спестила време?“ с „Как организира последната обща закуска?“. Избери неутралния въпрос и отдели факт, тълкуване и следваща проверка.\n\nСамопроверка: Въпросът не предлага желания отговор. „Писа за доставка“ е наблюдение; „ще купи веднага“ остава предположение.\n\nГраница: Разговорите са качествен сигнал, не анкета с представителна извадка. Не обещавай поверителност, ако нямаш контрол върху записа; вземи съгласие и записвай само необходимото.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да проведеш кратък разговор без да подтикваш човека към желаното от теб заключение. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Разговорите са качествен сигнал, не анкета с представителна извадка. Не обещавай поверителност, ако нямаш контрол върху записа; вземи съгласие и записвай само необходимото.\n\nКарта за работа — Задавай въпроси, които не подсказват отговора\n1. Започни с контекст и попитай най-скорошния случай.\n2. Нека човекът опише действията си; не прекъсвай, за да обясняваш продукта.\n3. Задай едно уточнение за момента на колебание или решение.\n4. Провери разбирането с неутрално обобщение и отбележи точните думи.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv01-05","module":"s02-m01","intro":"Ще превръщаш широка тема в полезен извод за един клип. Ще знаеш разликата между „за какво говорим“, „какъв е проблемът“ и „какво човекът ще разбере“.","objective":{"body":"Ще превръщаш широка тема в полезен извод за един клип. Ще знаеш разликата между „за какво говорим“, „какъв е проблемът“ и „какво човекът ще разбере“.","deliverable":"Раздели „закуска“, „неясно как се получава кутията“ и „кутията се взема от обекта след уточняване“. Използвай последното като извод за сценария.","check":"Темата, проблемът и изводът не са една и съща фраза. Клипът отговаря на избрания въпрос, без да започва история за цялата фирма."},"note":{"body":"Раздели „закуска“, „неясно как се получава кутията“ и „кутията се взема от обекта след уточняване“. Използвай последното като извод за сценария.\n\nСамопроверка: Темата, проблемът и изводът не са една и съща фраза. Клипът отговаря на избрания въпрос, без да започва история за цялата фирма.\n\nГраница: Не прескачай от една история към универсален съвет. Ако решението зависи от материал, модел камера, закон или индивидуално състояние, кажи при какви условия важи.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да превърнеш широка тема в конкретен проблем и извод за зрителя. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Не прескачай от една история към универсален съвет. Ако решението зависи от материал, модел камера, закон или индивидуално състояние, кажи при какви условия важи.\n\nКарта за работа — Раздели тема, проблем и полезен извод\n1. Запиши темата с едно съществително.\n2. Добави ситуация и наблюдавано затруднение с глагол.\n3. Посочи какво знаеш и кое е само предполагаема причина.\n4. Формулирай един извод, който можеш да покажеш, а не само да заявиш.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv01-06","module":"s02-m01","intro":"Ще избираш показател според целта на видеото. Ще различаваш започнато гледане, разбиране на условията, запитване и потвърдена поръчка.","objective":{"body":"Ще избираш показател според целта на видеото. Ще различаваш започнато гледане, разбиране на условията, запитване и потвърдена поръчка.","deliverable":"Прочети учебната таблица с две версии. Изчисли подходящите запитвания спрямо посещенията и запиши периода. Не наричай всички съобщения поръчки.","check":"Показателят има числител, знаменател и период. Броят гледания не доказва сам по себе си разбиране, продажба или причина за промяната."},"note":{"body":"Прочети учебната таблица с две версии. Изчисли подходящите запитвания спрямо посещенията и запиши периода. Не наричай всички съобщения поръчки.\n\nСамопроверка: Показателят има числител, знаменател и период. Броят гледания не доказва сам по себе си разбиране, продажба или причина за промяната.\n\nГраница: При малък обем една-две конверсии променят процента рязко. Посочи броя случаи до процента и не обявявай победител по шумни данни.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да избереш едно желано действие или разбиране и показател, който го приближава. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"При малък обем една-две конверсии променят процента рязко. Посочи броя случаи до процента и не обявявай победител по шумни данни.\n\nКарта за работа — Постави цел за зрителя, не за суетна метрика\n1. Назови едно действие или разбиране, което видеото цели да промени.\n2. Избери най-близкия наблюдаем показател и дефинирай знаменателя.\n3. Запиши изходния период и източника на данните.\n4. Преди публикация реши какъв сигнал ще наложи нова версия.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv01-07","module":"s02-m01","intro":"Ще свързваш края на видеото с една изпълнима следваща стъпка. Ще проверяваш дали зрителят разбира къде да я направи и какво ще стане след това.","objective":{"body":"Ще свързваш края на видеото с една изпълнима следваща стъпка. Ще проверяваш дали зрителят разбира къде да я направи и какво ще стане след това.","deliverable":"Избери между „Купи веднага“ и „Попитай за свободна кутия“. В условията няма система за плащане или потвърдена наличност.","check":"Призивът насочва към запитване. Не обещава поръчка, доставка или автоматично потвърждение, които процесът не може да изпълни."},"note":{"body":"Избери между „Купи веднага“ и „Попитай за свободна кутия“. В условията няма система за плащане или потвърдена наличност.\n\nСамопроверка: Призивът насочва към запитване. Не обещава поръчка, доставка или автоматично потвърждение, които процесът не може да изпълни.\n\nГраница: Не казвай „последни места“ или „само днес“, освен ако ограничението е реално и потвърдено. Спешността без факт руши доверие.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да избираш действие, което съответства на готовността и нуждата на зрителя. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Не казвай „последни места“ или „само днес“, освен ако ограничението е реално и потвърдено. Спешността без факт руши доверие.\n\nКарта за работа — Свържи целта с едно следващо действие\n1. Определи на кой етап е зрителят след видеото.\n2. Избери едно действие, което отговаря на липсващата му информация.\n3. Напиши точен призив и посочи къде се изпълнява.\n4. Провери, че връзката, датата и наличността са актуални.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv01-08","module":"s02-m01","intro":"Ще пишеш обещание, което може да бъде изпълнено с наличните кадри и факти. Ще виждаш кога красивата реплика обещава повече от самото предложение.","objective":{"body":"Ще пишеш обещание, което може да бъде изпълнено с наличните кадри и факти. Ще виждаш кога красивата реплика обещава повече от самото предложение.","deliverable":"Свери „6 малки банички за 9 €“ с утвърдените условия. Отхвърли „без глутен“, „безплатна доставка“ и „последни две кутии“, когато нямаш основание за тях.","check":"Всяко съществено твърдение има източник. Желанието за по-силен хук не променя продукта, условията или неизвестната наличност."},"note":{"body":"Свери „6 малки банички за 9 €“ с утвърдените условия. Отхвърли „без глутен“, „безплатна доставка“ и „последни две кутии“, когато нямаш основание за тях.\n\nСамопроверка: Всяко съществено твърдение има източник. Желанието за по-силен хук не променя продукта, условията или неизвестната наличност.\n\nГраница: Рекламни твърдения за цена, гаранция, резултат и ограничено време трябва да съвпадат с актуалните условия. Запази одобрения текст и датата на проверката.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да опишеш конкретната полза на видеото без гаранции, които не можеш да докажеш. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Рекламни твърдения за цена, гаранция, резултат и ограничено време трябва да съвпадат с актуалните условия. Запази одобрения текст и датата на проверката.\n\nКарта за работа — Формулирай обещание, което можеш да изпълниш\n1. Напиши обещанието с конкретен глагол и резултат.\n2. Сравни всяка част с кадър, тест, източник или реална демонстрация.\n3. Отбележи условията и изключенията, които променят резултата.\n4. Премахни гаранции за приходи, популярност и чужд избор.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv01-09","module":"s02-m01","intro":"Ще проверяваш с какво подкрепяш твърдение и имаш ли право да показваш материала. Ще различаваш собствен запис, разрешен клиентски материал и чужд кадър.","objective":{"body":"Ще проверяваш с какво подкрепяш твърдение и имаш ли право да показваш материала. Ще различаваш собствен запис, разрешен клиентски материал и чужд кадър.","deliverable":"Отбележи произхода на учебните графики и отдели кадрите, които трябва да заснемеш сам. За реална пекарна провери разрешенията, преди да включиш лице, музика или съобщение.","check":"За всеки използван материал са ясни произходът и разрешената употреба. Учебната графика не се представя като реален клиентски отзив или доказателство за производство."},"note":{"body":"Отбележи произхода на учебните графики и отдели кадрите, които трябва да заснемеш сам. За реална пекарна провери разрешенията, преди да включиш лице, музика или съобщение.\n\nСамопроверка: За всеки използван материал са ясни произходът и разрешената употреба. Учебната графика не се представя като реален клиентски отзив или доказателство за производство.\n\nГраница: Не показвай екрани с имена, телефони, адреси и лични съобщения. Разрешението за една платформа или кампания може да не покрива друга употреба.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да избираш доказателство, което е относимо, вярно и използвано с разрешение. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Не показвай екрани с имена, телефони, адреси и лични съобщения. Разрешението за една платформа или кампания може да не покрива друга употреба.\n\nКарта за работа — Провери какво доказваш и с чие разрешение\n1. Маркирай изреченията, които твърдят факт, резултат или сравнение.\n2. Прикачи първоизточник и провери дата, единици и ограничения.\n3. Получи разрешение за цитат, образ, музика и лични данни.\n4. Покажи доказателството до твърдението и пази контекста.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv01-10","module":"s02-m01","intro":"Ще намираш повтарящи се въпроси, от които могат да се получат смислени серии. Ще различаваш полезна тематична линия от повторена реклама на една услуга.","objective":{"body":"Ще намираш повтарящи се въпроси, от които могат да се получат смислени серии. Ще различаваш полезна тематична линия от повторена реклама на една услуга.","deliverable":"Подготви три линии за пекарната: какво получавам, как се получава и какво трябва да уточня предварително. За всяка посочи различен въпрос и възможен кадър.","check":"Трите идеи не повтарят една оферта с различни заглавия. Всяка има полезен отговор, който може да бъде показан."},"note":{"body":"Подготви три линии за пекарната: какво получавам, как се получава и какво трябва да уточня предварително. За всяка посочи различен въпрос и възможен кадър.\n\nСамопроверка: Трите идеи не повтарят една оферта с различни заглавия. Всяка има полезен отговор, който може да бъде показан.\n\nГраница: Не следвай безкрайно календар, ако повторен сигнал показва, че въпросът е решен или условията са се променили. Стълбовете са работна карта, не договор за вечност.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да организираш устойчиви теми около нуждите на аудиторията и своята доказуема експертиза. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Не следвай безкрайно календар, ако повторен сигнал показва, че въпросът е решен или условията са се променили. Стълбовете са работна карта, не договор за вечност.\n\nКарта за работа — Изгради теми, към които можеш да се връщаш\n1. Събери повтарящите се проблеми от разговори и обслужване.\n2. Свържи всеки проблем с умение или доказателство, което имаш.\n3. Групирай в малък брой разбираеми линии и дай на всяка различна роля.\n4. Провери дали можеш да произведеш примери и кадри устойчиво.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv01-11","module":"s02-m01","intro":"Ще генерираш идеи от конкретни въпроси и наблюдения. Ще можеш да предложиш няколко подхода към един проблем, без да измисляш нов факт заради оригиналност.","objective":{"body":"Ще генерираш идеи от конкретни въпроси и наблюдения. Ще можеш да предложиш няколко подхода към един проблем, без да измисляш нов факт заради оригиналност.","deliverable":"По въпроса „Колко са в кутията?“ предложи демонстрация, сравнение и кратък отговор. Избери вариант, който можеш да изпълниш с шест предмета или с ясно обозначена графика.","check":"Идеите сменят начина на обяснение, не броя, цената или условията. Избраната идея има осигурим материал."},"note":{"body":"По въпроса „Колко са в кутията?“ предложи демонстрация, сравнение и кратък отговор. Избери вариант, който можеш да изпълниш с шест предмета или с ясно обозначена графика.\n\nСамопроверка: Идеите сменят начина на обяснение, не броя, цената или условията. Избраната идея има осигурим материал.\n\nГраница: Идея от коментар не означава автоматично право да включиш потребителя в клипа. Използвай въпроса без идентифициращи детайли или поискай разрешение.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да превръщаш реален въпрос в няколко различни, приложими видео идеи. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Идея от коментар не означава автоматично право да включиш потребителя в клипа. Използвай въпроса без идентифициращи детайли или поискай разрешение.\n\nКарта за работа — Генерирай идеи от въпросите, не от празен лист\n1. Запиши конкретния въпрос с думите на човека.\n2. Създай поне три форми: демонстрация, обяснение и сравнение.\n3. За всяка избери кадър или факт, който ще носи стойността.\n4. Провери дали идеята се побира в цел, време, права и наличен ресурс.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv01-12","module":"s02-m01","intro":"Ще избираш идея по полезност, доказуемост и възможност за изпълнение. Ще знаеш кога обещанието трябва да бъде отказано, дори идеята да изглежда привлекателна.","objective":{"body":"Ще избираш идея по полезност, доказуемост и възможност за изпълнение. Ще знаеш кога обещанието трябва да бъде отказано, дори идеята да изглежда привлекателна.","deliverable":"Сравни показване на съдържанието, шега за обща закуска и твърдение за гарантирани поръчки. Посочи фактите, нужните материали и най-сериозния риск на всеки вариант.","check":"Невярно твърдение или липсващо разрешение спира идеята. Голям сбор точки за „интересно“ не компенсира този пропуск."},"note":{"body":"Сравни показване на съдържанието, шега за обща закуска и твърдение за гарантирани поръчки. Посочи фактите, нужните материали и най-сериозния риск на всеки вариант.\n\nСамопроверка: Невярно твърдение или липсващо разрешение спира идеята. Голям сбор точки за „интересно“ не компенсира този пропуск.\n\nГраница: При регулирана област, безопасност или репутационен риск, съответствието и съгласието са праг, а не точки за компенсация.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да сравниш идеи по полезност, доказуемост и възможност за производство. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"При регулирана област, безопасност или репутационен риск, съответствието и съгласието са праг, а не точки за компенсация.\n\nКарта за работа — Избери идея с ясни критерии\n1. Определи нуждата и зрителя, за които идеята е предназначена.\n2. Провери доказателства, разрешения и налични материали.\n3. Оцени очакваната полезност, производствената цена и мястото на разпространение.\n4. Избери победителя и запиши защо е по-добър от следващия вариант.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv01-13","module":"s02-m01","intro":"Ще планираш информацията според това, което зрителят вече знае. Ще можеш да различиш видео за първо запознаване от видео за човек, който сравнява условията.","objective":{"body":"Ще планираш информацията според това, което зрителят вече знае. Ще можеш да различиш видео за първо запознаване от видео за човек, който сравнява условията.","deliverable":"Направи две кратки версии: едната показва какво има в кутията, другата обяснява получаването. Запази цената и съществените ограничения и в двете.","check":"Различният акцент не крие важно условие. Зрителят знае какво е предложението и какво още трябва да уточни."},"note":{"body":"Направи две кратки версии: едната показва какво има в кутията, другата обяснява получаването. Запази цената и съществените ограничения и в двете.\n\nСамопроверка: Различният акцент не крие важно условие. Зрителят знае какво е предложението и какво още трябва да уточни.\n\nГраница: Не използвай скрити условия като механизъм за конверсия. Цена, срок, достъпност и ограничения трябва да са видими преди зрителят да вземе решение.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да опишеш какво знае и какво още му трябва преди следващата стъпка. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Не използвай скрити условия като механизъм за конверсия. Цена, срок, достъпност и ограничения трябва да са видими преди зрителят да вземе решение.\n\nКарта за работа — Начертай пътя на зрителя до видеото\n1. Назови какво знае зрителят преди видеото.\n2. Изброй един въпрос или риск, който още не е покрит.\n3. Избери съдържание, което затваря тази липса без да преувеличава.\n4. Свържи края с подходяща следваща страница, урок или демонстрация.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv01-14","module":"s02-m01","intro":"Ще избираш формат според информацията и средата на гледане. Ще преценяваш дали смисълът остава ясен на телефон и без звук.","objective":{"body":"Ще избираш формат според информацията и средата на гледане. Ще преценяваш дали смисълът остава ясен на телефон и без звук.","deliverable":"За учебния бриф избери вертикален клип 9:16 с продължителност 25 секунди. Сравни го с хоризонтална демонстрация, преди да приемеш формата като правило за всеки проект.","check":"Размерът и времето изпълняват този бриф, не универсален стандарт. Броят, цената и получаването се разбират и от текста в кадъра."},"note":{"body":"За учебния бриф избери вертикален клип 9:16 с продължителност 25 секунди. Сравни го с хоризонтална демонстрация, преди да приемеш формата като правило за всеки проект.\n\nСамопроверка: Размерът и времето изпълняват този бриф, не универсален стандарт. Броят, цената и получаването се разбират и от текста в кадъра.\n\nГраница: Точните размери, ограничения и безопасни зони зависят от конкретното място за публикуване и могат да се променят. Проверявай актуалните указания преди финален експорт.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да съобразиш формат, продължителност и начин на гледане с идеята. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Точните размери, ограничения и безопасни зони зависят от конкретното място за публикуване и могат да се променят. Проверявай актуалните указания преди финален експорт.\n\nКарта за работа — Избери формат според задачата и мястото на гледане\n1. Избери една задача на видеото: да покаже, обясни, сравни или разкаже.\n2. Напиши кои елементи трябва да се виждат или чуват, за да я изпълнят.\n3. Избери ориентация, кадриране и продължителност според канала и материала.\n4. Провери читаемост на телефон, без звук и при реалната скорост на гледане.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv01-15","module":"s02-m01","intro":"Ще анализираш пример по видими решения: кога се появява въпросът, доказателството и следващата стъпка. Ще отделяш наблюдението от предположението защо нещо работи.","objective":{"body":"Ще анализираш пример по видими решения: кога се появява въпросът, доказателството и следващата стъпка. Ще отделяш наблюдението от предположението защо нещо работи.","deliverable":"Разгледай учебния клип с времеви маркери. Запиши какво се показва на 00:03, 00:09 и 00:21 и какъв въпрос изяснява всяка част.","check":"Бележката сочи конкретен момент. „Цената се вижда на 00:09“ е наблюдение; „това увеличава продажбите“ е хипотеза за отделен тест."},"note":{"body":"Разгледай учебния клип с времеви маркери. Запиши какво се показва на 00:03, 00:09 и 00:21 и какъв въпрос изяснява всяка част.\n\nСамопроверка: Бележката сочи конкретен момент. „Цената се вижда на 00:09“ е наблюдение; „това увеличава продажбите“ е хипотеза за отделен тест.\n\nГраница: Гледанията често зависят от платено разпространение, аудитория и момент. Разглеждай референцията като материал за анализ, не като рецепта за алгоритъм.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да разложиш пример на конкретни визуални и редакционни решения. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Гледанията често зависят от платено разпространение, аудитория и момент. Разглеждай референцията като материал за анализ, не като рецепта за алгоритъм.\n\nКарта за работа — Разгледай референция по решенията, не само по усещането\n1. Избери референция със сходна задача или зрител.\n2. Опиши наблюдаеми решения във времева линия, без оценки като „яко“.\n3. Свържи всяко решение с предполагаем ефект и маркирай това като хипотеза.\n4. Избери един принцип за тест, не копирай целия монтаж.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv01-16","module":"s02-m01","intro":"Ще пренасяш полезен принцип от референция в собствена идея. Ще можеш да отделиш реда на информацията от чуждите реплики, кадри и музика.","objective":{"body":"Ще пренасяш полезен принцип от референция в собствена идея. Ще можеш да отделиш реда на информацията от чуждите реплики, кадри и музика.","deliverable":"Запази принципа „въпрос → съдържание → условия → действие“ и го приложи към втория учебен бизнес. Смени продукта, кадрите, цената и ограничението.","check":"Новият сценарий отговаря на новите условия. Не копира чужд материал и не оставя стара цена или обещание за доставка."},"note":{"body":"Запази принципа „въпрос → съдържание → условия → действие“ и го приложи към втория учебен бизнес. Смени продукта, кадрите, цената и ограничението.\n\nСамопроверка: Новият сценарий отговаря на новите условия. Не копира чужд материал и не оставя стара цена или обещание за доставка.\n\nГраница: Идеята или общият формат обикновено не е равен на разрешение за използване на конкретен кадър, текст, музика или изпълнение. Провери правата за всеки актив.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да създадеш оригинален подход, като отделиш механиката от израза. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Идеята или общият формат обикновено не е равен на разрешение за използване на конкретен кадър, текст, музика или изпълнение. Провери правата за всеки актив.\n\nКарта за работа — Вземи принципа от референцията, не чуждото видео\n1. Назови какво точно работи като принцип: контраст, последователност или демонстрация.\n2. Извади отличителни думи, образи, музика и графики от чуждия материал.\n3. Замени примера с твои наблюдения и доказателства.\n4. Провери, че новата версия има собствена гледна точка и права.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv01-17","module":"s02-m01","intro":"Ще събираш решенията в кратък бриф, по който друг човек може да започне работа. Ще виждаш кои липси трябва да бъдат уточнени преди снимане.","objective":{"body":"Ще събираш решенията в кратък бриф, по който друг човек може да започне работа. Ще виждаш кои липси трябва да бъдат уточнени преди снимане.","deliverable":"Попълни за пекарната зрител, въпрос, обещание, източник, формат, действие, ограничения и начин за приемане. Използвай готовия учебен пример след своя опит.","check":"Брифът съдържа 6 броя, 9 €, вземане от обекта и запитване за наличност. Не включва недоказано твърдение за качество или резултат."},"note":{"body":"Попълни за пекарната зрител, въпрос, обещание, източник, формат, действие, ограничения и начин за приемане. Използвай готовия учебен пример след своя опит.\n\nСамопроверка: Брифът съдържа 6 броя, 9 €, вземане от обекта и запитване за наличност. Не включва недоказано твърдение за качество или резултат.\n\nГраница: Брифът е жив документ до одобрението на концепцията. След промяна на цел, цена или дата, обнови версията и уведоми екипа.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да събереш цел, аудитория, обещание, доказателство и производствени ограничения. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Брифът е жив документ до одобрението на концепцията. След промяна на цел, цена или дата, обнови версията и уведоми екипа.\n\nКарта за работа — Напиши едностраничен творчески бриф\n1. Попълни зрителя, момент и проблем от наличните наблюдения.\n2. Напиши обещание и доказателство, които си проверил.\n3. Посочи формат, призив за действие, ограничения и какво не включва проектът.\n4. Потвърди собственик на одобрението, срок и критерии за приемане.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv01-18","module":"s02-m01","intro":"Ще намираш конкретен ъгъл към широка тема. Ще различаваш интересна гледна точка от по-шумно заглавие, което не променя съдържанието.","objective":{"body":"Ще намираш конкретен ъгъл към широка тема. Ще различаваш интересна гледна точка от по-шумно заглавие, което не променя съдържанието.","deliverable":"Сравни „Нашите банички“ с „Закуска за шестима: какво има в една кутия?“. Избери ъгъл, който може да се покаже и който отговаря на учебните реакции.","check":"Има конкретен въпрос и материал за отговора. Изненадата не зависи от измислен риск, дефицит или неудобно положение на човек."},"note":{"body":"Сравни „Нашите банички“ с „Закуска за шестима: какво има в една кутия?“. Избери ъгъл, който може да се покаже и който отговаря на учебните реакции.\n\nСамопроверка: Има конкретен въпрос и материал за отговора. Изненадата не зависи от измислен риск, дефицит или неудобно положение на човек.\n\nГраница: Не превръщай уязвимостта, страх или здравословно притеснение в сензационен трик. Дръж тона уважителен и обещанието изпълнимо.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да избираш гледна точка, която добавя смисъл към позната тема. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Не превръщай уязвимостта, страх или здравословно притеснение в сензационен трик. Дръж тона уважителен и обещанието изпълнимо.\n\nКарта за работа — Намери ъгъла, който прави темата конкретна\n1. Запиши широка тема без рекламна украса.\n2. Назови конкретното напрежение или въпрос на зрителя.\n3. Избери една гледна точка, която можеш да покажеш с материал.\n4. Сравни поне две версии за яснота, оригиналност и доказуемост.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv01-19","module":"s02-m01","intro":"Ще превеждаш твърдение в необходим кадър. Ще знаеш кога декоративният материал не доказва това, което репликата казва.","objective":{"body":"Ще превеждаш твърдение в необходим кадър. Ще знаеш кога декоративният материал не доказва това, което репликата казва.","deliverable":"Свържи „6 броя“ с видими шест предмета, цената с актуалните условия и получаването с четим надпис. За истински продукт замени учебната схема със собствен разрешен запис.","check":"Всяка важна реплика има подходящ образ или източник. Графика на банички не удостоверява реален състав, вкус или производствен процес."},"note":{"body":"Свържи „6 броя“ с видими шест предмета, цената с актуалните условия и получаването с четим надпис. За истински продукт замени учебната схема със собствен разрешен запис.\n\nСамопроверка: Всяка важна реплика има подходящ образ или източник. Графика на банички не удостоверява реален състав, вкус или производствен процес.\n\nГраница: Не обещавай, че монтажът може да поправи липсващо доказателство. Ако не можеш да снимаш основния факт, промени сценария преди снимачния ден.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да превърнеш брифа в материал, който зрителят може да наблюдава. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Не обещавай, че монтажът може да поправи липсващо доказателство. Ако не можеш да снимаш основния факт, промени сценария преди снимачния ден.\n\nКарта за работа — Планирай какво трябва да се види\n1. Маркирай всяка реплика или текст, който носи важно твърдение.\n2. Избери наблюдаемо доказателство и най-четим план за него.\n3. Добави реакционен, установяващ и детайлен кадър, ако наративът ги изисква.\n4. Провери, че кадрите не разкриват лични данни или чужда работа без право.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv01-20","module":"s02-m01","intro":"Ще оценяваш какво можеш да произведеш с наличните време, място и техника. Ще подготвяш резервен ход за зависимост, която не е осигурена.","objective":{"body":"Ще оценяваш какво можеш да произведеш с наличните време, място и техника. Ще подготвяш резервен ход за зависимост, която не е осигурена.","deliverable":"Планирай задача с телефон, прозорец и шест предмета на маса. Ако нямаш разрешен продукт или тихо място, използвай графичния маршрут и отбележи границата му.","check":"Планът може да се изпълни без покупка на техника. Няма обещан реален кадър, лице или локация, до които нямаш разрешен достъп."},"note":{"body":"Планирай задача с телефон, прозорец и шест предмета на маса. Ако нямаш разрешен продукт или тихо място, използвай графичния маршрут и отбележи границата му.\n\nСамопроверка: Планът може да се изпълни без покупка на техника. Няма обещан реален кадър, лице или локация, до които нямаш разрешен достъп.\n\nГраница: При шум, разрешения или достъп, които не могат да се осигурят, не разчитай на обещание „ще го оправим в монтаж“. Подготви алтернативен сценарий.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да направиш план, който може да се произведе при реалните ограничения. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"При шум, разрешения или достъп, които не могат да се осигурят, не разчитай на обещание „ще го оправим в монтаж“. Подготви алтернативен сценарий.\n\nКарта за работа — Оцени място, време и налични ресурси\n1. Огледай мястото по време на планирания час и запиши шум, светлина и фон.\n2. Потвърди достъп, съгласие, захранване, карта памет и транспорт.\n3. Събери нужната екипировка по функция и провери съвместимостта.\n4. Определи резервен кадър, място или време за най-големия риск.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv01-21","module":"s02-m01","intro":"Ще подреждаш снимачния ден по зависимости, а не по реда на готовия клип. Ще запазваш еднаквото състояние на предметите между свързани кадри.","objective":{"body":"Ще подреждаш снимачния ден по зависимости, а не по реда на готовия клип. Ще запазваш еднаквото състояние на предметите между свързани кадри.","deliverable":"Групирай общия план, шестте предмета и детайла на една маса. Запиши къде стои кутията и кога се променя броят, преди да снимаш втори дубъл.","check":"Снимачният ред спестява пренастройване, но не нарушава логиката на монтажа. Има време за тест и копие на файловете."},"note":{"body":"Групирай общия план, шестте предмета и детайла на една маса. Запиши къде стои кутията и кога се променя броят, преди да снимаш втори дубъл.\n\nСамопроверка: Снимачният ред спестява пренастройване, но не нарушава логиката на монтажа. Има време за тест и копие на файловете.\n\nГраница: Не притискай хората да работят извън уговореното или в небезопасни условия, за да спазиш изкуствен график. Реалното ограничение се съобщава на клиента и се решава преди деня.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да подредиш задачи така, че хората и ресурсите да чакат възможно най-малко. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Не притискай хората да работят извън уговореното или в небезопасни условия, за да спазиш изкуствен график. Реалното ограничение се съобщава на клиента и се решава преди деня.\n\nКарта за работа — Подреди деня на снимане по зависимости\n1. Раздели сценария на кадри, локации, хора и реквизит.\n2. Групирай по настройка, като запиши непрекъснатостта на реквизита, което трябва да остане еднакво.\n3. Добави буфер, тестов дубъл, паузи и резервно копиране.\n4. Раздай снимачния график за екипа с часове, адрес, контакт, разрешения и кой одобрява.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv01-22","module":"s02-m01","intro":"Ще проверяваш кратък запис преди основното снимане. Ще търсиш конкретни дефекти в картина и звук, вместо да приемаш светналия индикатор за доказателство.","objective":{"body":"Ще проверяваш кратък запис преди основното снимане. Ще търсиш конкретни дефекти в картина и звук, вместо да приемаш светналия индикатор за доказателство.","deliverable":"Запиши десет секунди при реалната светлина. Отвори файла, провери фокуса и прослушай, ако има говор. При графичния маршрут отбележи, че няма микрофонен запис.","check":"Прегледан е самият файл, не само екранът по време на запис. Не форматираш карта, на която е единственото копие."},"note":{"body":"Запиши десет секунди при реалната светлина. Отвори файла, провери фокуса и прослушай, ако има говор. При графичния маршрут отбележи, че няма микрофонен запис.\n\nСамопроверка: Прегледан е самият файл, не само екранът по време на запис. Не форматираш карта, на която е единственото копие.\n\nГраница: Не отваряй и не форматирай карта с единствено копие на материала. Потвърди резервното копие преди освобождаване на носителя.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да хванеш проблеми със звук, кадър, съгласие и съдържание преди основния дубъл. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Не отваряй и не форматирай карта с единствено копие на материала. Потвърди резервното копие преди освобождаване на носителя.\n\nКарта за работа — Направи техническа и редакционна проверка преди запис\n1. Провери заряд, място, формат, фокус и цвят на камерата.\n2. Запиши 10 секунди с човека на реалното му място и прослушай.\n3. Провери кадър за фон, надписи, права и неволно разкрити данни.\n4. Потвърди основния кадър и резервен вариант с отговорния човек.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv01-23","module":"s02-m01","intro":"Ще планираш тест, който може да промени следващата версия. Ще различаваш сигнал за затруднение от доказана причина за него.","objective":{"body":"Ще планираш тест, който може да промени следващата версия. Ще различаваш сигнал за затруднение от доказана причина за него.","deliverable":"Прочети отчета за A и B и посочи различните периоди, аудитории и бюджет. Планирай нова проверка на ранното получаване при съпоставими условия и еднакво определение за подходящо запитване.","check":"Изводът посочва ограниченията на данните. Не очакваш автоматични „ключови моменти“ за 25-секунден клип, когато конкретният платформен отчет има други условия."},"note":{"body":"Прочети отчета за A и B и посочи различните периоди, аудитории и бюджет. Планирай нова проверка на ранното получаване при съпоставими условия и еднакво определение за подходящо запитване.\n\nСамопроверка: Изводът посочва ограниченията на данните. Не очакваш автоматични „ключови моменти“ за 25-секунден клип, когато конкретният платформен отчет има други условия.\n\nГраница: При малък обем или различни аудитории отбележи резултата като посока, не като сигурен победител. При платформени промени първо провери как се дефинира текущата метрика.\n\nПри следващия сигнал сравни същия канал и период с изходната точка. Ако новият източник противоречи на първия, провери дали се е променило поведение, аудитория или условията, преди да смениш извод.\n\nПоследен тест: ако колега не може да намери източника или да повтори периода, остави изводът като предположение. Не представяй извадка от разговори като представителна статистика.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да формулираш хипотеза и правило за следваща итерация. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"При малък обем или различни аудитории отбележи резултата като посока, не като сигурен победител. При платформени промени първо провери как се дефинира текущата метрика.\n\nПри следващия сигнал сравни същия канал и период с изходната точка. Ако новият източник противоречи на първия, провери дали се е променило поведение, аудитория или условията, преди да смениш извод.\n\nПоследен тест: ако колега не може да намери източника или да повтори периода, остави изводът като предположение. Не представяй извадка от разговори като представителна статистика.\n\nКарта за работа — Планирай как ще научиш от резултата\n1. Запиши хипотезата и една промяна, която ще тестваш.\n2. Определи показателя, знаменател, период и източник преди публикация.\n3. Сравни с релевантен базов клип и отбележи външни промени.\n4. Реши: запази, преработи или събери още данни; не обявявай причинност без дизайн.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата.\n\nАктуална справка: YouTube Help — Audience retention and engagement: https://support.google.com/youtube/answer/9313698?hl=en (провери актуалната версия преди публикуване)."}}},{"lesson":"pv01-24","module":"s02-m01","intro":"Ще завършиш първия модул с бриф и изпълним снимачен план за един клип. Това е подготовка за производство, не доказателство, че клипът вече е създаден или успешен.","objective":{"body":"Ще завършиш първия модул с бриф и изпълним снимачен план за един клип. Това е подготовка за производство, не доказателство, че клипът вече е създаден или успешен.","deliverable":"Събери решенията за „Зърно“ и премини проверката на брифа. После отвори различния учебен бизнес и промени фактите, без да копираш първото решение.","check":"Друг човек може да разбере зрителя, обещанието, материалите и границите. Старото завършване на урока не отбелязва новата проверка като премината."},"note":{"body":"Събери решенията за „Зърно“ и премини проверката на брифа. После отвори различния учебен бизнес и промени фактите, без да копираш първото решение.\n\nСамопроверка: Друг човек може да разбере зрителя, обещанието, материалите и границите. Старото завършване на урока не отбелязва новата проверка като премината.\n\nГраница: Не предавай пароли, лични данни или необработени клиентски файлове чрез отворена папка. Сподели само нужните активи по одобрен канал.\n\nПреди предаване: съвпадат ли дата и период; можеш ли да посочиш първоизточника; маркирано ли е неизвестното; има ли разрешение за всеки човек и актив?\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да предадеш проект, по който сценаристът и снимачният екип могат да започнат работа. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Не предавай пароли, лични данни или необработени клиентски файлове чрез отворена папка. Сподели само нужните активи по одобрен канал.\n\nПреди предаване: съвпадат ли дата и период; можеш ли да посочиш първоизточника; маркирано ли е неизвестното; има ли разрешение за всеки човек и актив?\n\nКарта за работа — Събери брифа и плана за производство\n1. Събери последната одобрена версия на брифа и посланието.\n2. Прикачи списък с кадри, места, хора, реквизит, права и тестове.\n3. Напиши изискванията за предаване и критерии за приемане по канала.\n4. Маркирай зависимостите, неизвестните и следващия отговорник.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv02-01","module":"s02-m02","intro":"Ще оставяш на клипа една ясна работа. Ще можеш да премахнеш сцена, която не помага на избрания зрител, дори сама по себе си да е интересна.","objective":{"body":"Ще оставяш на клипа една ясна работа. Ще можеш да премахнеш сцена, която не помага на избрания зрител, дори сама по себе си да е интересна.","deliverable":"За първия клип запази въпроса какво получавам и как го вземам. Извади историята на фирмата и втори продукт в отделни идеи.","check":"Всички части подкрепят една задача. Ясната цел не е обещание за конкретен брой гледания или поръчки."},"note":{"body":"За първия клип запази въпроса какво получавам и как го вземам. Извади историята на фирмата и втори продукт в отделни идеи.\n\nСамопроверка: Всички части подкрепят една задача. Ясната цел не е обещание за конкретен брой гледания или поръчки.\n\nГраница: Една цел за видеото не означава, че бизнесът има само един показател. Тя означава, че зрителят трябва да получи едно ясно обещание и един логичен път.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да сведеш сценария до една промяна, която зрителят трябва да разбере или направи. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Една цел за видеото не означава, че бизнесът има само един показател. Тя означава, че зрителят трябва да получи едно ясно обещание и един логичен път.\n\nКарта за работа — Остави на видеото една ясна работа\n1. Вземи целта и зрителя от одобрения бриф.\n2. Напиши едно наблюдаемо завършване на изречението „след видеото…“.\n3. Провери всяка желана сцена спрямо целта и доказателството.\n4. Изнеси второстепенните теми в следващо видео или описание.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv02-02","module":"s02-m02","intro":"Ще избираш гледна точка преди началната реплика. Така ще можеш да напишеш различни концепции, които отговарят на един и същ въпрос.","objective":{"body":"Ще избираш гледна точка преди началната реплика. Така ще можеш да напишеш различни концепции, които отговарят на един и същ въпрос.","deliverable":"Подготви демонстрация на кутията и сравнение на неясно с ясно условие за получаване. Избери коя концепция може да се изпълни с наличните материали.","check":"Концепцията определя образ и развитие, не само заглавие. Фактите остават едни и същи във всички варианти."},"note":{"body":"Подготви демонстрация на кутията и сравнение на неясно с ясно условие за получаване. Избери коя концепция може да се изпълни с наличните материали.\n\nСамопроверка: Концепцията определя образ и развитие, не само заглавие. Фактите остават едни и същи във всички варианти.\n\nГраница: Гледната точка може да се промени, когато ново наблюдение опровергае предположението. Не защитавай първата формулировка само защото вече си написал хук.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да превърнеш темата от брифа в конкретна гледна точка за сценария. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Гледната точка може да се промени, когато ново наблюдение опровергае предположението. Не защитавай първата формулировка само защото вече си написал хук.\n\nКарта за работа — Намери гледната точка преди първия ред\n1. Запиши темата без рекламно заглавие.\n2. Избери конкретния въпрос или погрешно очакване на зрителя.\n3. Напиши гледната точка в едно изречение, без да обещаваш прекалено.\n4. Провери дали има кадър, факт или демонстрация, които я доказват.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv02-03","module":"s02-m02","intro":"Ще пишеш начало, което привлича внимание с истински въпрос и после отговаря на него. Ще проверяваш връзката между обещаното и показаното.","objective":{"body":"Ще пишеш начало, което привлича внимание с истински въпрос и после отговаря на него. Ще проверяваш връзката между обещаното и показаното.","deliverable":"Сравни „Закуска за шестима?“ с „Няма да повярваш какво крият пекарните“. Свържи избрания хук с кадъра, който показва съдържанието на кутията.","check":"Видеото изпълнява очакването от първите секунди. Не задържа съществено условие само за да удължи гледането."},"note":{"body":"Сравни „Закуска за шестима?“ с „Няма да повярваш какво крият пекарните“. Свържи избрания хук с кадъра, който показва съдържанието на кутията.\n\nСамопроверка: Видеото изпълнява очакването от първите секунди. Не задържа съществено условие само за да удължи гледането.\n\nГраница: Любопитството е полезно, но не задържай основна информация, която зрителят очаква, само за да удължиш гледането.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да започнеш сценария с конкретно твърдение, въпрос или образ, който видеото после оправдава. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Любопитството е полезно, но не задържай основна информация, която зрителят очаква, само за да удължиш гледането.\n\nКарта за работа — Напиши хук, който изпълнява обещанието\n1. Назови обещанието, което зрителят ще чуе или види.\n2. Избери кадър/реплика, който показва същия проблем или резултат.\n3. Премахни общите уводи и неподкрепените твърдения.\n4. Провери дали следващите сцени дават отговор, а не сменят темата.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv02-04","module":"s02-m02","intro":"Ще избираш първи образ, който се разпознава на малък екран. Ще преценяваш кога действие, детайл или реплика ориентира по-добре от дълго представяне.","objective":{"body":"Ще избираш първи образ, който се разпознава на малък екран. Ще преценяваш кога действие, детайл или реплика ориентира по-добре от дълго представяне.","deliverable":"Пробвай начало с шест предмета и начало само с лого. Запиши какво зрителят разбира от всеки вариант преди първата подробност.","check":"Основният обект се вижда и без звук. Логото може да присъства, но не замества отговора на въпроса за продукта."},"note":{"body":"Пробвай начало с шест предмета и начало само с лого. Запиши какво зрителят разбира от всеки вариант преди първата подробност.\n\nСамопроверка: Основният обект се вижда и без звук. Логото може да присъства, но не замества отговора на въпроса за продукта.\n\nГраница: Кадър с изненадващ резултат трябва да бъде от същата демонстрация и контекст. Не създавай впечатление за момент, който не се случва във видеото.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да избираш начин на отваряне според това каква информация може да се покаже най-рано. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Кадър с изненадващ резултат трябва да бъде от същата демонстрация и контекст. Не създавай впечатление за момент, който не се случва във видеото.\n\nКарта за работа — Започни с действие, образ или реплика\n1. Избери визуален знак, който се разбира без предварителен контекст.\n2. Определи къде е погледът и какво се движи в кадъра.\n3. Добави само нужния надпис или звук, за да се разчете действието.\n4. Провери първия кадър без звук и на малък екран.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv02-05","module":"s02-m02","intro":"Ще подреждаш сценария така, че всяка част да добавя нужна информация. Ще можеш да обясниш защо даден кадър идва преди следващия.","objective":{"body":"Ще подреждаш сценария така, че всяка част да добавя нужна информация. Ще можеш да обясниш защо даден кадър идва преди следващия.","deliverable":"Раздели 25 секунди на въпрос, съдържание, цена, получаване и действие. Посочи какъв нов отговор дава всяка част.","check":"Времената не се припокриват и сборът е 25 секунди. Редът остава разбираем без допълнителен разказ от автора."},"note":{"body":"Раздели 25 секунди на въпрос, съдържание, цена, получаване и действие. Посочи какъв нов отговор дава всяка част.\n\nСамопроверка: Времената не се припокриват и сборът е 25 секунди. Редът остава разбираем без допълнителен разказ от автора.\n\nГраница: Не налагай механично триактен разказ на всяка демонстрация. Прост процес може да е най-ясен като последователност от наблюдаеми стъпки.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да изградиш последователност от контекст, напрежение, избор и резултат. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Не налагай механично триактен разказ на всяка демонстрация. Прост процес може да е най-ясен като последователност от наблюдаеми стъпки.\n\nКарта за работа — Подреди сценария на ясни части\n1. Отбележи обещанието и въпроса, който ще бъде отговорен.\n2. Подреди необходимия контекст преди стъпката, която зависи от него.\n3. Постави доказателството след твърдението, но достатъчно рано за проверка.\n4. Завърши с резултат и призив за действие, който продължава темата.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv02-06","module":"s02-m02","intro":"Ще създаваш интерес чрез конкретен въпрос и полезен отговор. Ще различаваш напрежението в историята от измислен страх, конфликт или недостиг.","objective":{"body":"Ще създаваш интерес чрез конкретен въпрос и полезен отговор. Ще различаваш напрежението в историята от измислен страх, конфликт или недостиг.","deliverable":"Покажи неудобството „не знам как се получава кутията“ и го разреши с точно условие. Не добавяй „само днес“ или „последни две“, ако не са потвърдени.","check":"Залогът идва от реалната задача на зрителя. Споделянето остава възможна реакция, не гарантирано следствие от избрана емоция."},"note":{"body":"Покажи неудобството „не знам как се получава кутията“ и го разреши с точно условие. Не добавяй „само днес“ или „последни две“, ако не са потвърдени.\n\nСамопроверка: Залогът идва от реалната задача на зрителя. Споделянето остава възможна реакция, не гарантирано следствие от избрана емоция.\n\nГраница: При тема за безопасност или пари, ясно кажи сериозността и точния риск; не превръщай предупреждението нито в сензация, нито в забавен фон.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да поддържаш интерес с въпрос, препятствие и отговор, които са реални за темата. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"При тема за безопасност или пари, ясно кажи сериозността и точния риск; не превръщай предупреждението нито в сензация, нито в забавен фон.\n\nКарта за работа — Създай напрежение без да подвеждаш\n1. Назови какво иска човекът в тази сцена.\n2. Определи реалната пречка, която може да се види или обясни.\n3. Покажи опит, обратна връзка и последствие.\n4. Провери, че разрешението е честно и не обещава еднакъв резултат за всички.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv02-07","module":"s02-m02","intro":"Ще даваш информацията в ред, в който човек може да я използва. Ще виждаш кога екранът и репликата едновременно искат прекалено много внимание.","objective":{"body":"Ще даваш информацията в ред, в който човек може да я използва. Ще виждаш кога екранът и репликата едновременно искат прекалено много внимание.","deliverable":"Покажи първо кутията и броя, после цената и получаването. Сравни с кадър, в който всички условия се появяват наведнъж с дребен текст.","check":"Нужната информация може да бъде прочетена в реалното време на кадъра. Не премахваш условие заради по-бърз монтаж."},"note":{"body":"Покажи първо кутията и броя, после цената и получаването. Сравни с кадър, в който всички условия се появяват наведнъж с дребен текст.\n\nСамопроверка: Нужната информация може да бъде прочетена в реалното време на кадъра. Не премахваш условие заради по-бърз монтаж.\n\nГраница: Не повтаряй едно и също с глас, надпис, анимация и графика, ако това претрупва екрана. Всеки канал трябва да носи различна опора или да е излишен.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да подредиш информацията така, че зрителят да може да следва решението. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Не повтаряй едно и също с глас, надпис, анимация и графика, ако това претрупва екрана. Всеки канал трябва да носи различна опора или да е излишен.\n\nКарта за работа — Дай новата информация в правилния ред\n1. Установи обекта и задачата преди да използваш „това“ или „така“.\n2. Дай само контекста, който е нужен за следващото действие.\n3. Показвай стъпките в логичен ред и оставяй време за ключовия детайл.\n4. Добави изключение след основния случай, не преди зрителят да го разбере.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv02-08","module":"s02-m02","intro":"Ще планираш демонстрация, която показва действие и резултат. Ще знаеш какво синтетичен материал може да обясни и какво не може да докаже.","objective":{"body":"Ще планираш демонстрация, която показва действие и резултат. Ще знаеш какво синтетичен материал може да обясни и какво не може да докаже.","deliverable":"За собствен запис покажи празна кутия, поставяне на шест предмета и крайния брой. За графичната версия обозначи, че това е учебна схема, не реално производство.","check":"Няма пропусната стъпка, която променя смисъла. Генериран кадър не се представя като доказателство за действителен вкус, текстура или качество."},"note":{"body":"За собствен запис покажи празна кутия, поставяне на шест предмета и крайния брой. За графичната версия обозначи, че това е учебна схема, не реално производство.\n\nСамопроверка: Няма пропусната стъпка, която променя смисъла. Генериран кадър не се представя като доказателство за действителен вкус, текстура или качество.\n\nГраница: Не редактирай демонстрацията така, че да премахнеш стъпка, която е нужна за безопасност или правилен резултат.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да превърнеш обяснението в наблюдаема демонстрация. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Не редактирай демонстрацията така, че да премахнеш стъпка, която е нужна за безопасност или правилен резултат.\n\nКарта за работа — Покажи процеса, вместо само да го твърдиш\n1. Раздели умението на видимо начално състояние и критично движение.\n2. Избери план, който не скрива инструмента, ръцете или посоката.\n3. Запиши поне един дубъл на действието и един на последствието.\n4. Съпостави репликата и кадъра; отбележи всеки монтажен скок.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv02-09","module":"s02-m02","intro":"Ще подкрепяш точното твърдение с точния източник. Ще виждаш разликата между условие на офертата, демонстрация и мнение на зрител.","objective":{"body":"Ще подкрепяш точното твърдение с точния източник. Ще виждаш разликата между условие на офертата, демонстрация и мнение на зрител.","deliverable":"Посочи източник за 6 броя, 9 € и вземане от обекта. Сравни ги със старата бележка за 8 € и с учебната реакция, която пита за доставка.","check":"Старата цена и желанието за доставка не променят утвърдените условия. Реакцията е учебен материал, не клиентски отзив."},"note":{"body":"Посочи източник за 6 броя, 9 € и вземане от обекта. Сравни ги със старата бележка за 8 € и с учебната реакция, която пита за доставка.\n\nСамопроверка: Старата цена и желанието за доставка не променят утвърдените условия. Реакцията е учебен материал, не клиентски отзив.\n\nГраница: Когато използваш чужди данни, цитирай коректно и спазвай лицензионните условия; цитатът сам по себе си не дава право да копираш цяла таблица или видео.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да използваш източник, пример или тест, който действително подкрепя твърдението. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Когато използваш чужди данни, цитирай коректно и спазвай лицензионните условия; цитатът сам по себе си не дава право да копираш цяла таблица или видео.\n\nКарта за работа — Подкрепи твърдението с проверимо доказателство\n1. Маркирай всяко проверимо твърдение в текста.\n2. Провери първоизточник, дата и точни условия.\n3. Съпостави доказателството с формулировката и нужната аудитория.\n4. Покажи цитат/данни с контекст и отбележи връзката между тях.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv02-10","module":"s02-m02","intro":"Ще използваш пример, който прави трудната идея разбираема, без да я подменя. Ще назоваваш къде сравнението спира да е точно.","objective":{"body":"Ще използваш пример, който прави трудната идея разбираема, без да я подменя. Ще назоваваш къде сравнението спира да е точно.","deliverable":"Обясни разкадровката като план „какво се вижда във всяка част“. После покажи петте части на клипа и отдели плана от готовия видеофайл.","check":"Човекът разбира термина чрез конкретния пример. Наличието на план не се представя като заснет или проверен клип."},"note":{"body":"Обясни разкадровката като план „какво се вижда във всяка част“. После покажи петте части на клипа и отдели плана от готовия видеофайл.\n\nСамопроверка: Човекът разбира термина чрез конкретния пример. Наличието на план не се представя като заснет или проверен клип.\n\nГраница: В безопасност, здраве, право и финанси не оставяй метафората да замени точната препоръка или условие.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да използваш аналогия или демонстрация, без тя да изкривява темата. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"В безопасност, здраве, право и финанси не оставяй метафората да замени точната препоръка или условие.\n\nКарта за работа — Обясни трудна идея с точен пример\n1. Назови частта от идеята, която затруднява зрителя.\n2. Избери познат предмет или действие със сходна една характеристика.\n3. Кажи къде сравнението спира да е вярно.\n4. Покажи реалния процес и върни вниманието към точния термин.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv02-11","module":"s02-m02","intro":"Ще определяш тон с конкретни думи и поведение, а не със суперлативи. Ще използваш творческа роля като ориентир за разказа, без да поставяш психологически етикети на зрителя.","objective":{"body":"Ще определяш тон с конкретни думи и поведение, а не със суперлативи. Ще използваш творческа роля като ориентир за разказа, без да поставяш психологически етикети на зрителя.","deliverable":"Сравни глас на спокоен майстор с глас на закачлив домакин. Пренапиши една реплика за всеки, като запазиш 6 броя, 9 € и условието за получаване.","check":"Различен тон не означава различна истина. Архетипът е творчески избор, не диагноза, а цветът не доказва тип личност или готовност за покупка."},"note":{"body":"Сравни глас на спокоен майстор с глас на закачлив домакин. Пренапиши една реплика за всеки, като запазиш 6 броя, 9 € и условието за получаване.\n\nСамопроверка: Различен тон не означава различна истина. Архетипът е творчески избор, не диагноза, а цветът не доказва тип личност или готовност за покупка.\n\nГраница: Не сменяй диалект, акцент или езиково ниво като комична характеристика. Хуморът не трябва да унижава говорителя.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да редактираш репликите така, че да звучат естествено и да пазят фактите. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Не сменяй диалект, акцент или езиково ниво като комична характеристика. Хуморът не трябва да унижава говорителя.\n\nКарта за работа — Пиши в своя глас, не в рекламна поза\n1. Събери одобрени примери за естествения говор на човека.\n2. Маркирай клишета, неподкрепени прилагателни и неестествени обещания.\n3. Пренапиши с конкретен глагол и думите, които аудиторията използва.\n4. Провери фактическата точност и произнеси репликите на глас.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv02-12","module":"s02-m02","intro":"Ще превръщаш писан текст в ясни произносими мисли. Ще запазваш числата, отрицанията и условията, които променят предложението.","objective":{"body":"Ще превръщаш писан текст в ясни произносими мисли. Ще запазваш числата, отрицанията и условията, които променят предложението.","deliverable":"Прочети „Шест малки банички за девет евро. Вземат се от обекта. Попитай за свободна кутия.“ Отдели дъховете и измери времето с обикновен таймер.","check":"Репликата се разбира от първо слушане. Съкращаването не премахва „от обекта“ или превръща запитването в потвърдена поръчка."},"note":{"body":"Прочети „Шест малки банички за девет евро. Вземат се от обекта. Попитай за свободна кутия.“ Отдели дъховете и измери времето с обикновен таймер.\n\nСамопроверка: Репликата се разбира от първо слушане. Съкращаването не премахва „от обекта“ или превръща запитването в потвърдена поръчка.\n\nГраница: Не режи условие или отрицание само за да стане по-кратко. „Не натискай още“ и „натискай още“ звучат сходно, но водят до противоположно действие.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да превърнеш писмен текст в реплики, които лесно се произнасят и слушат. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Не режи условие или отрицание само за да стане по-кратко. „Не натискай още“ и „натискай още“ звучат сходно, но водят до противоположно действие.\n\nКарта за работа — Раздели текста на дъхове и мисли\n1. Прочети текста на глас с естествена скорост и запиши време.\n2. Отбележи места за дъх, неясни местоимения и сложни натрупвания.\n3. Раздели идеите, като запазиш причината и условието.\n4. Направи пробен запис и провери разбираемост през слушалки.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv02-13","module":"s02-m02","intro":"Ще избираш начин за изпълнение на текста според задачата. Ще можеш да запазиш точните условия, без да караш говорителя да звучи наизуст.","objective":{"body":"Ще избираш начин за изпълнение на текста според задачата. Ще можеш да запазиш точните условия, без да караш говорителя да звучи наизуст.","deliverable":"Направи собствен прочит по три опорни точки: съдържание, условия и действие. Ако няма говорител, подготви текстова графична версия със същия смисъл.","check":"Няма измислена реакция на клиент. Гласът или надписите предават едни и същи проверени условия."},"note":{"body":"Направи собствен прочит по три опорни точки: съдържание, условия и действие. Ако няма говорител, подготви текстова графична версия със същия смисъл.\n\nСамопроверка: Няма измислена реакция на клиент. Гласът или надписите предават едни и същи проверени условия.\n\nГраница: Не принуждавай човек да споделя лична история или емоционална реакция заради „по-автентичен кадър“. Съгласието важи и за начина на представяне.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да използваш репетиция, ключови точки и поведение пред камерата за естествено изпълнение. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Не принуждавай човек да споделя лична история или емоционална реакция заради „по-автентичен кадър“. Съгласието важи и за начина на представяне.\n\nКарта за работа — Изпълни сценария без да звучиш наизуст\n1. Раздели сценария на мисли и маркирай факти, които не бива да се променят.\n2. Избери телесуфльор, опорни точки или демонстрация според задачата.\n3. Репетирай с кадър и звук; коригирай поглед, темпо и действия.\n4. Запиши чист дубъл и резервен дубъл, като запазиш еднакви условия.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv02-14","module":"s02-m02","intro":"Ще използваш пауза и темпо, за да се разбере важният момент. Ще проверяваш дали човек действително има време да види действието и прочете надписа.","objective":{"body":"Ще използваш пауза и темпо, за да се разбере важният момент. Ще проверяваш дали човек действително има време да види действието и прочете надписа.","deliverable":"Сравни задържане на цената за една секунда и за няколко секунди. Прегледай при нормална скорост на телефон, не само в редактора кадър по кадър.","check":"Броят, цената и получаването са четими в наличното време. Най-бързият монтаж не се приема по подразбиране за най-полезен."},"note":{"body":"Сравни задържане на цената за една секунда и за няколко секунди. Прегледай при нормална скорост на телефон, не само в редактора кадър по кадър.\n\nСамопроверка: Броят, цената и получаването са четими в наличното време. Най-бързият монтаж не се приема по подразбиране за най-полезен.\n\nГраница: При субтитри, инструкции и числа остави екранното време за реално прочитане. Темпото на монтаж не е заместител на четливостта.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да регулираш скоростта според сложността, емоцията и нуждата от разбиране. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"При субтитри, инструкции и числа остави екранното време за реално прочитане. Темпото на монтаж не е заместител на четливостта.\n\nКарта за работа — Използвай паузи и темпо за смисъл\n1. Маркирай в сценария местата с висока когнитивна трудност.\n2. Сними действията в реално време и добави отделен чист детайл.\n3. Реши къде паузата носи напрежение, разбиране или въздух.\n4. Провери монтаж без музика, за да чуеш истинското темпо.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv02-15","module":"s02-m02","intro":"Ще пишеш призив, който естествено продължава видеото. Ще посочваш какво да направи човекът и какво се очаква след това.","objective":{"body":"Ще пишеш призив, който естествено продължава видеото. Ще посочваш какво да направи човекът и какво се очаква след това.","deliverable":"Завърши с „Попитай за свободна кутия“. При реална публикация посочи действителния разрешен канал и провери дали той приема запитването.","check":"Призивът е един и изпълним. Учебният прототип не се представя като свързан с поръчки, плащане или реална наличност."},"note":{"body":"Завърши с „Попитай за свободна кутия“. При реална публикация посочи действителния разрешен канал и провери дали той приема запитването.\n\nСамопроверка: Призивът е един и изпълним. Учебният прототип не се представя като свързан с поръчки, плащане или реална наличност.\n\nГраница: Призив за коментар, абонамент или покупка трябва да има причина и да не изисква лична информация публично.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да формулираш едно ясно действие, което е уместно за стойността и готовността на зрителя. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Призив за коментар, абонамент или покупка трябва да има причина и да не изисква лична информация публично.\n\nКарта за работа — Напиши призив, който следва от видеото\n1. Определи каква информация вече има зрителят.\n2. Избери едно действие, което помага да реши оставащия въпрос.\n3. Назови връзката, бутона или мястото за следващата стъпка.\n4. Провери, че целевата страница е актуална и изпълнява обещанието.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата.\n\nДопълнителен теренен тест: Преди публикуване отвори целевата страница от телефон и провери, че съвпадат име, цена, срок и следваща стъпка. Скрито условие или неактивен линк превръща добрия призив в подвеждащ."}}},{"lesson":"pv02-16","module":"s02-m02","intro":"Ще адаптираш акцента за различна готовност на зрителя. Ще запазваш важните условия и когато човекът тепърва научава за предложението.","objective":{"body":"Ще адаптираш акцента за различна готовност на зрителя. Ще запазваш важните условия и когато човекът тепърва научава за предложението.","deliverable":"Направи начало за първо запознаване и начало за човек, който вече пита как да получи кутията. Остави едни и същи цена, брой и ограничение.","check":"Версиите отговарят на различен въпрос, без да използват скрита цена или измислени чувствителни характеристики за таргетиране."},"note":{"body":"Направи начало за първо запознаване и начало за човек, който вече пита как да получи кутията. Остави едни и същи цена, брой и ограничение.\n\nСамопроверка: Версиите отговарят на различен въпрос, без да използват скрита цена или измислени чувствителни характеристики за таргетиране.\n\nГраница: Не използвай чувствителни лични данни или чувствителни характеристики за таргетиране без законно основание и ясни правила.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да адаптираш акцента за зрител, който тепърва учи, сравнява решения или е готов за действие. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Не използвай чувствителни лични данни или чувствителни характеристики за таргетиране без законно основание и ясни правила.\n\nКарта за работа — Подготви версия за различна готовност на зрителя\n1. Назови етапа и нерешения въпрос на всеки сегмент.\n2. Запази общия доказуем факт и основното обещание.\n3. Промени началото, пример или призив за действие според нуждата.\n4. Провери, че всички версии са точни и не си противоречат.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv02-17","module":"s02-m02","intro":"Ще адаптираш сценария към конкретното място за публикуване. Ще различаваш изискване на платформата от работна препоръка на автора.","objective":{"body":"Ще адаптираш сценария към конкретното място за публикуване. Ще различаваш изискване на платформата от работна препоръка на автора.","deliverable":"Провери вертикалния файл, текста и следващото действие в целевия предпреглед. Ако ползваш друг канал, запиши датата на проверката и неговите условия.","check":"Информацията не се закрива от интерфейса. Няма универсална безопасна зона или обещание, че един файл е подходящ навсякъде."},"note":{"body":"Провери вертикалния файл, текста и следващото действие в целевия предпреглед. Ако ползваш друг канал, запиши датата на проверката и неговите условия.\n\nСамопроверка: Информацията не се закрива от интерфейса. Няма универсална безопасна зона или обещание, че един файл е подходящ навсякъде.\n\nГраница: Указанията за формат и интерфейс се променят. Не разпространявай един точен размер като вечен стандарт; отвори официалната документация преди голяма кампания.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да промениш кадри, начални контекст и темпо според средата, като запазиш смисъла. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Указанията за формат и интерфейс се променят. Не разпространявай един точен размер като вечен стандарт; отвори официалната документация преди голяма кампания.\n\nКарта за работа — Адаптирай сценария към платформата без да го копираш на сляпо\n1. Определи къде и как видеото ще бъде открито и гледано.\n2. Пази главния обект и важния текст в безопасна композиция за този интерфейс.\n3. Настрой първите секунди и призива за реалния път на зрителя.\n4. Провери финалната публикация в приложението и потвърди връзките.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv02-18","module":"s02-m02","intro":"Ще планираш сравнение на две версии с една ясна промяна. Ще пресмяташ показателя правилно и ще посочваш кога данните не позволяват сигурен извод.","objective":{"body":"Ще планираш сравнение на две версии с една ясна промяна. Ще пресмяташ показателя правилно и ще посочваш кога данните не позволяват сигурен извод.","deliverable":"В учебния отчет версия A има 20 подходящи запитвания от 400 посещения. Пресметни процента и сравни с версия B, без да наричаш резултата причинен само от хука.","check":"20/400 × 100 = 5%. Отчетът показва наблюдавана разлика; без контрол на аудиторията, периода и разпространението не доказва победител."},"note":{"body":"В учебния отчет версия A има 20 подходящи запитвания от 400 посещения. Пресметни процента и сравни с версия B, без да наричаш резултата причинен само от хука.\n\nСамопроверка: 20/400 × 100 = 5%. Отчетът показва наблюдавана разлика; без контрол на аудиторията, периода и разпространението не доказва победител.\n\nГраница: Платформеният инструмент може да тества само конкретен елемент и да използва собствена метрика. Прочети актуалните условия на функцията преди да пренасяш извод към друго видео.\n\nКогато пробният зрител не може да повтори обещанието, намери първата сцена, в която темата се отклонява. Поправи това звено и провери отново; не пренаписвай автоматично целия сценарий.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да сравниш варианти, без да приписваш разликата на грешен фактор. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Платформеният инструмент може да тества само конкретен елемент и да използва собствена метрика. Прочети актуалните условия на функцията преди да пренасяш извод към друго видео.\n\nКогато пробният зрител не може да повтори обещанието, намери първата сцена, в която темата се отклонява. Поправи това звено и провери отново; не пренаписвай автоматично целия сценарий.\n\nКарта за работа — Тествай две версии с една ясна хипотеза\n1. Напиши A/B хипотеза: кой елемент и какъв резултат ще промени.\n2. Направи варианти, които се различават само по този елемент.\n3. Избери метрика и минимални условия за сравнение преди пускане.\n4. Запиши резултат, ограничения и следващия тест, включително когато няма победител.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата.\n\nАктуална справка: YouTube Help — Test & compare миниатюри: https://support.google.com/youtube/answer/13861714?hl=en (провери актуалната версия преди публикуване)."}}},{"lesson":"pv02-19","module":"s02-m02","intro":"Ще съкращаваш сценария, без да изрязваш решаващ факт. Ще проверяваш отделно текст, образ и времетраене.","objective":{"body":"Ще съкращаваш сценария, без да изрязваш решаващ факт. Ще проверяваш отделно текст, образ и времетраене.","deliverable":"Премахни повторението на „вкусна закуска“, преди да режеш цената или вземането от обекта. Прегледай версията без звук и направи отделен прочит на репликите.","check":"След редакцията брой, цена, получаване и действие остават разбираеми. Броят думи не замества реалното време за показване и четене."},"note":{"body":"Премахни повторението на „вкусна закуска“, преди да режеш цената или вземането от обекта. Прегледай версията без звук и направи отделен прочит на репликите.\n\nСамопроверка: След редакцията брой, цена, получаване и действие остават разбираеми. Броят думи не замества реалното време за показване и четене.\n\nГраница: Ограничение по дължина не оправдава скрито условие. Ако нужната информация не се побира, избери друг формат или раздели темата.\n\nНаправи и по-кратка версия, но първо реши кой пример или повторение да махнеш. Остави обещанието, доказателството и нужната граница; прочети версията на глас и провери кадъра без звук.\n\nПоследен тест: чути само репликите, видеото пак трябва да има ясна мисъл; видени без звук, кадрите трябва да показват основното действие. Ако двете версии си противоречат, сценарият още не е готов.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да съкратиш сценария, без да махнеш доказателството и нужния контекст. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Ограничение по дължина не оправдава скрито условие. Ако нужната информация не се побира, избери друг формат или раздели темата.\n\nНаправи и по-кратка версия, но първо реши кой пример или повторение да махнеш. Остави обещанието, доказателството и нужната граница; прочети версията на глас и провери кадъра без звук.\n\nПоследен тест: чути само репликите, видеото пак трябва да има ясна мисъл; видени без звук, кадрите трябва да показват основното действие. Ако двете версии си противоречат, сценарият още не е готов.\n\nКарта за работа — Редактирай сценария за яснота и време\n1. Прочети текста на глас и измери естественото време.\n2. Маркирай повторения и изречения, които не променят разбирането.\n3. Пази твърдение, доказателство, условие и следваща стъпка.\n4. Провери новия монтаж с човек, който не е писал сценария.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv02-20","module":"s02-m02","intro":"Ще завършиш сценарий, по който могат да се подготвят кадри, звук и надписи. Ще различаваш този документ от готовия клип и от доказан резултат при публикация.","objective":{"body":"Ще завършиш сценарий, по който могат да се подготвят кадри, звук и надписи. Ще различаваш този документ от готовия клип и от доказан резултат при публикация.","deliverable":"Събери петте части на 25-секундния клип с време, образ, текст и източник. Използвай графичната версия или заснеми свой материал по същия план.","check":"Сборът е 25 секунди; всяка реплика има опора. Непотвърдена наличност и стари цени не се промъкват между сцените."},"note":{"body":"Събери петте части на 25-секундния клип с време, образ, текст и източник. Използвай графичната версия или заснеми свой материал по същия план.\n\nСамопроверка: Сборът е 25 секунди; всяка реплика има опора. Непотвърдена наличност и стари цени не се промъкват между сцените.\n\nГраница: Сценарий „готов за снимане“ не означава, че всеки кадър е гарантиран. Посочи зависимостите и кой решава, ако условие се промени.\n\nПреди монтаж: прочети сценария на глас; гледай пробния кадър без звук; провери дали кадърът доказва репликата; виж дали призивът води точно към обещаната информация.\n\nРаботна карта за сценария: време; въпрос на зрителя; реплика; кадър, който я доказва; надпис; преход; призив за действие; факт или условие за одобрение. Ако кадърът не носи репликата, промени сценария преди снимането.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да предадеш сценарий с текст, кадри, доказателства и начин за проверка. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Сценарий „готов за снимане“ не означава, че всеки кадър е гарантиран. Посочи зависимостите и кой решава, ако условие се промени.\n\nПреди монтаж: прочети сценария на глас; гледай пробния кадър без звук; провери дали кадърът доказва репликата; виж дали призивът води точно към обещаната информация.\n\nРаботна карта за сценария: време; въпрос на зрителя; реплика; кадър, който я доказва; надпис; преход; призив за действие; факт или условие за одобрение. Ако кадърът не носи репликата, промени сценария преди снимането.\n\nКарта за работа — Подготви сценарий, готов за снимане\n1. Раздели сценария на части и оцени времето с пробен прочит.\n2. Попълни паралелно картина, звук, надпис и доказателство.\n3. Посочи права, хора, реквизит, място и резервен вариант.\n4. Провери версията, сроковете, спецификацията и критериите за приемане.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv03-01","module":"s02-m03","intro":"Ще избираш кадрова честота според движение, светлина и крайна доставка. Ще разбираш защо повече кадри в секунда не означават автоматично по-добър клип.","objective":{"body":"Ще избираш кадрова честота според движение, светлина и крайна доставка. Ще разбираш защо повече кадри в секунда не означават автоматично по-добър клип.","deliverable":"За учебния снимачен план използвай 25 кадъра/секунда и запиши причината. При собствен телефон провери какво действително предлага приложението; не смесвай честоти случайно.","check":"Настройката и крайният файл са съгласувани. Графичният пример не доказва как конкретната камера ще се държи при светодиодна лампа."},"note":{"body":"За учебния снимачен план използвай 25 кадъра/секунда и запиши причината. При собствен телефон провери какво действително предлага приложението; не смесвай честоти случайно.\n\nСамопроверка: Настройката и крайният файл са съгласувани. Графичният пример не доказва как конкретната камера ще се държи при светодиодна лампа.\n\nГраница: Не смесвай произволно 24, 25, 30 и 60 кадъра/секунда в един монтаж. Ако смесването е необходимо, определи как редакторът ще обработи всеки източник.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да избереш кадрова честота според движението, желаното възпроизвеждане и възможностите на устройството. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Не смесвай произволно 24, 25, 30 и 60 кадъра/секунда в един монтаж. Ако смесването е необходимо, определи как редакторът ще обработи всеки източник.\n\nКарта за работа — Избери кадровата честота за движението и доставката\n1. Определи дали действието трябва да изглежда в реално време или забавено.\n2. Провери електрическото осветление и ограниченията на камерата.\n3. Настрой кадрите/секунда в камерата и проекта преди запис.\n4. Сними кратък тест и провери движението на реалния екран.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv03-02","module":"s02-m03","intro":"Ще свързваш кадровата честота с времето на експонация и размазването при движение. Ще различаваш отправната точка от настройка, която трябва да се изпита при конкретната светлина.","objective":{"body":"Ще свързваш кадровата честота с времето на експонация и размазването при движение. Ще различаваш отправната точка от настройка, която трябва да се изпита при конкретната светлина.","deliverable":"При 25 кадъра/секунда един кадър трае 0,04 секунди. Пресметни половината от това време: 0,02 секунди, или 1/50. После запиши собствен кратък тест, ако приложението позволява ръчна настройка.","check":"Не бъркаш честота с време: при отправна точка 180° експонацията е половината от времето на кадъра, не двойно по-дълга. Мигането се проверява в запис, не се изключва само по формулата."},"note":{"body":"При 25 кадъра/секунда един кадър трае 0,04 секунди. Пресметни половината от това време: 0,02 секунди, или 1/50. После запиши собствен кратък тест, ако приложението позволява ръчна настройка.\n\nСамопроверка: Не бъркаш честота с време: при отправна точка 180° експонацията е половината от времето на кадъра, не двойно по-дълга. Мигането се проверява в запис, не се изключва само по формулата.\n\nГраница: При бързо действие, спорт, графика или намерено усещане може да избереш по-различен затвор. Направи това съзнателно и покажи теста на клиента.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да разпознаваш как времето на експонация влияе на размазването при движение. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"При бързо действие, спорт, графика или намерено усещане може да избереш по-различен затвор. Направи това съзнателно и покажи теста на клиента.\n\nКарта за работа — Настрой затвора според движението\n1. Избери кадри/секунда и зададената естетика на движението.\n2. Постави затвора като начална точка около двойната честота.\n3. Коригирай експозицията със светлина, диафрагма или ND, не със случайни промени.\n4. Запиши тест с панорама и осветлението включено; търси мигане.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv03-03","module":"s02-m03","intro":"Ще оценяваш експозицията по важния детайл, а не само по яркостта на екрана. Ще знаеш кога промяна на светлината е по-полезна от увеличаване на ISO.","objective":{"body":"Ще оценяваш експозицията по важния детайл, а не само по яркостта на екрана. Ще знаеш кога промяна на светлината е по-полезна от увеличаване на ISO.","deliverable":"Снимай светъл предмет до прозорец и провери дали контурът му се запазва. Промени само една настройка или позицията спрямо светлината и сравни файловете.","check":"Важният детайл не е изгорял, а сенките не са повдигнати на сляпо. Отбелязваш какво е променено между двата теста."},"note":{"body":"Снимай светъл предмет до прозорец и провери дали контурът му се запазва. Промени само една настройка или позицията спрямо светлината и сравни файловете.\n\nСамопроверка: Важният детайл не е изгорял, а сенките не са повдигнати на сляпо. Отбелязваш какво е променено между двата теста.\n\nГраница: Правилната експозиция зависи от сцената и естетиката. Не клипвай важен детайл и не изравнявай умишлено контраст, ако това вреди на образа.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да намалиш шум и загуба на детайл чрез правилна експозиция и разумен избор на светлина. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Правилната експозиция зависи от сцената и естетиката. Не клипвай важен детайл и не изравнявай умишлено контраст, ако това вреди на образа.\n\nКарта за работа — Експонирай чисто преди да вдигаш ISO\n1. Настрой кадрова честота и затвор за движението.\n2. Постави светлина така, че важните тонове да са отчетливи.\n3. Следи светлите части и сенките с наличните инструменти.\n4. Повиши ISO само колкото е нужно и запиши тест за шум.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv03-04","module":"s02-m03","intro":"Ще избираш фокус според движението на обекта. Ще проверяваш дали фокусът остава върху действието, а не върху случайния фон.","objective":{"body":"Ще избираш фокус според движението на обекта. Ще проверяваш дали фокусът остава върху действието, а не върху случайния фон.","deliverable":"Премести ръка с предмет към кутията и запиши десет секунди. Сравни следящ и заключен фокус, ако устройството ги предлага.","check":"Във файла ключовият предмет е четим в момента на действието. Името на настройката в менюто не замества прегледа."},"note":{"body":"Премести ръка с предмет към кутията и запиши десет секунди. Сравни следящ и заключен фокус, ако устройството ги предлага.\n\nСамопроверка: Във файла ключовият предмет е четим в момента на действието. Името на настройката в менюто не замества прегледа.\n\nГраница: Лицевият автофокус зависи от модела и настройките. Не приемай, че всяка камера еднакво разпознава лице, очила, профил или ръце.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да избираш между автофокус, заключен фокус и ръчен фокус според сцената. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Лицевият автофокус зависи от модела и настройките. Не приемай, че всяка камера еднакво разпознава лице, очила, профил или ръце.\n\nКарта за работа — Дръж фокуса върху важното\n1. Определи кой обект трябва да остане рязък през всяка част.\n2. Избери режим и тествай с истинското движение на човека.\n3. Провери фокус в началото, средата и края на дубъла.\n4. Запиши резервен дубъл и не мести предметите след заключване.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv03-05","module":"s02-m03","intro":"Ще пазиш последователен цвят между свързани кадри. Ще различаваш баланс на бялото от експозиция и от проблем със смесени лампи.","objective":{"body":"Ще пазиш последователен цвят между свързани кадри. Ще различаваш баланс на бялото от експозиция и от проблем със смесени лампи.","deliverable":"Постави неутрален лист под светлината на предмета. Сравни два последователни записа и заключи баланса, ако приложението позволява.","check":"Белият ориентир не сменя оттенъка без причина. Не използваш цветовата корекция, за да внушиш качество на продукт, което не е показано."},"note":{"body":"Постави неутрален лист под светлината на предмета. Сравни два последователни записа и заключи баланса, ако приложението позволява.\n\nСамопроверка: Белият ориентир не сменя оттенъка без причина. Не използваш цветовата корекция, за да внушиш качество на продукт, което не е показано.\n\nГраница: Персоналният баланс не поправя различния спектър на евтини/смесени лампи напълно. Провери кожата на екран и премахни източник, който прави петно, ако може.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да поддържаш постоянен цвят на кожата и предметите между дублите. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Персоналният баланс не поправя различния спектър на евтини/смесени лампи напълно. Провери кожата на екран и премахни източник, който прави петно, ако може.\n\nКарта за работа — Заключи баланса на бялото за последователни цветове\n1. Постави човека/предмета в реалната светлина на сцената.\n2. Използвай карта или фиксиран готов режим или стойност в Kelvin като отправна точка.\n3. Заключи баланса и снимай референсен кадър.\n4. Сравни два кадъра при същото осветление и коригирай източника.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv03-06","module":"s02-m03","intro":"Ще подготвяш стаята за разбираема картина и използваем звук. Ще можеш да намериш най-слабото звено, преди да добавяш техника.","objective":{"body":"Ще подготвяш стаята за разбираема картина и използваем звук. Ще можеш да намериш най-слабото звено, преди да добавяш техника.","deliverable":"Отдалечи предмета от шумния фон и пробвай светлина от прозорец. Ако има реплика, запиши я отблизо и я прослушай със слушалки.","check":"Няма изключено важно оборудване заради кадъра. При графичен клип без говор отбелязваш липсата на микрофонен тест, вместо да го обявяваш за преминат."},"note":{"body":"Отдалечи предмета от шумния фон и пробвай светлина от прозорец. Ако има реплика, запиши я отблизо и я прослушай със слушалки.\n\nСамопроверка: Няма изключено важно оборудване заради кадъра. При графичен клип без говор отбелязваш липсата на микрофонен тест, вместо да го обявяваш за преминат.\n\nГраница: Не спирай климатизация, аспирация или друго важно оборудване, ако това създава риск или нарушава условията. Използвай микрофон и планирай репликата в безопасен момент.\n\nПреди да изтриеш теста: гледай фокус и движение на голям екран; слушай през слушалки; сравни цветовете между дублите; отвори изнесения файл на целевия телефон.\n\nАко преместиш снимането в друга стая или смениш камера/телефон, повтори теста. Не пренасяй стойностите по памет: друга светлина, дистанция и сензор променят резултата.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да използваш наличната светлина и място за четим образ и разбираем глас. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Не спирай климатизация, аспирация или друго важно оборудване, ако това създава риск или нарушава условията. Използвай микрофон и планирай репликата в безопасен момент.\n\nПреди да изтриеш теста: гледай фокус и движение на голям екран; слушай през слушалки; сравни цветовете между дублите; отвори изнесения файл на целевия телефон.\n\nАко преместиш снимането в друга стая или смениш камера/телефон, повтори теста. Не пренасяй стойностите по памет: друга светлина, дистанция и сензор променят резултата.\n\nКарта за работа — Подготви светлина, фон и звук в стаята\n1. Огледай светлината, отраженията, шумовете и захранването.\n2. Постави микрофона близо до устата и обезопаси кабела.\n3. Направи тестов запис с реалния фон и прослушай със слушалки.\n4. Подреди фон и светлина, после запиши тих запис на помещението.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv03-07","module":"s02-m03","intro":"Ще проверяваш изнесения файл според конкретния бриф. Ще различаваш размер, кадрова честота, кодек и действителна възможност за възпроизвеждане.","objective":{"body":"Ще проверяваш изнесения файл според конкретния бриф. Ще различаваш размер, кадрова честота, кодек и действителна възможност за възпроизвеждане.","deliverable":"Отвори изнесения файл на целевото устройство. За този учебен проект търси вертикален кадър 9:16 и 25 секунди; запиши формата, който редакторът или браузърът действително е създал.","check":"Файлът се възпроизвежда. Проверка на размер и време не удостоверява автоматично звук, фокус, права, кодек или готовност за всяка платформа."},"note":{"body":"Отвори изнесения файл на целевото устройство. За този учебен проект търси вертикален кадър 9:16 и 25 секунди; запиши формата, който редакторът или браузърът действително е създал.\n\nСамопроверка: Файлът се възпроизвежда. Проверка на размер и време не удостоверява автоматично звук, фокус, права, кодек или готовност за всяка платформа.\n\nГраница: Кодекът, битрейтът, максималната продължителност и правилата за формат се обновяват. Използвай официалната страница на платформата за доставката в деня на публикуване.\n\nКогато клипът не минава проверка, отдели запис, монтаж и експорт: отвори оригинала, после кадъра в проекта, после финалния файл. Така няма да преснимаш проблем, възникнал при експорта.\n\nПоследен тест: сравни оригиналния запис с финалния файл на целевия телефон. Провери движение, фокус, цвят, четим текст и звук; ако проблемът се вижда само във финала, поправи експорта, не преснимай сцената.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да съчетаеш резолюция, кадрова честота, формат и качество при експортиране. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Кодекът, битрейтът, максималната продължителност и правилата за формат се обновяват. Използвай официалната страница на платформата за доставката в деня на публикуване.\n\nКогато клипът не минава проверка, отдели запис, монтаж и експорт: отвори оригинала, после кадъра в проекта, после финалния файл. Така няма да преснимаш проблем, възникнал при експорта.\n\nПоследен тест: сравни оригиналния запис с финалния файл на целевия телефон. Провери движение, фокус, цвят, четим текст и звук; ако проблемът се вижда само във финала, поправи експорта, не преснимай сцената.\n\nКарта за работа — Запази файл, който отговаря на целевия екран\n1. Потвърди целевата платформа, ориентация, резолюция и максимална дължина.\n2. Сравни изхода с източника: кадри/секунда, цвят, аудио и пропорции.\n3. Експортирай тестов сегмент и провери текст, движение и звук на телефон.\n4. Отвори финалния файл, провери началото/края и качи без повторно прекодиране, ако е възможно.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата.\n\nАктуална справка: YouTube Help — Recommended upload encoding settings: https://support.google.com/youtube/answer/1722171?hl=en (провери актуалната версия преди публикуване)."}}},{"lesson":"pv03-08","module":"s02-m03","intro":"Ще планираш кадъра така, че необходимото действие да остане видимо и във вертикална версия. Ще знаеш кога е нужен отделен дубъл вместо механично изрязване.","objective":{"body":"Ще планираш кадъра така, че необходимото действие да остане видимо и във вертикална версия. Ще знаеш кога е нужен отделен дубъл вместо механично изрязване.","deliverable":"Постави кутията и шестте предмета в кадър. Направи вертикална проба и провери дали броят и движението на ръката остават видими.","check":"Основната информация не е отрязана. Интерфейсът и надписите се проверяват на целевия екран, не с универсални координати."},"note":{"body":"Постави кутията и шестте предмета в кадър. Направи вертикална проба и провери дали броят и движението на ръката остават видими.\n\nСамопроверка: Основната информация не е отрязана. Интерфейсът и надписите се проверяват на целевия екран, не с универсални координати.\n\nГраница: Точната safe зона зависи от интерфейса, бутони и устройство. Провери актуалния предпреглед на всяко място; няма една вечна рамка за всички приложения.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да планираш композицията така, че основният смисъл да остане видим в избрания формат. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Точната safe зона зависи от интерфейса, бутони и устройство. Провери актуалния предпреглед на всяко място; няма една вечна рамка за всички приложения.\n\nКарта за работа — Кадрирай за вертикално и хоризонтално гледане\n1. Определи главен формат и вторични места за публикуване.\n2. Планирай безопасна рамка/зона за ръце, лице, графика и субтитри.\n3. Сними тестов кадър и прекадрирай за всяко отношение на страните.\n4. Провери двата файла в реалните приложения и на телефон.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv03-09","module":"s02-m03","intro":"Ще различаваш приближаване с обектив от промяна на позицията на камерата. Ще можеш да обясниш защо близкият предмет изглежда различно спрямо фона.","objective":{"body":"Ще различаваш приближаване с обектив от промяна на позицията на камерата. Ще можеш да обясниш защо близкият предмет изглежда различно спрямо фона.","deliverable":"Заснеми една кутия отблизо и от по-далеч с подобен размер в кадъра. Сравни отношението между предната и задната част.","check":"Записана е позицията на камерата. Цифровото изрязване не се представя като промяна на перспективата."},"note":{"body":"Заснеми една кутия отблизо и от по-далеч с подобен размер в кадъра. Сравни отношението между предната и задната част.\n\nСамопроверка: Записана е позицията на камерата. Цифровото изрязване не се представя като промяна на перспективата.\n\nГраница: Телефоните могат да превключват между отделни модули и цифрово изрязване. Провери истинската камера и фокусно разстояние в метаданните, когато геометрията е важна.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да избираш позиция и обектив според пространството и характера на кадъра. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Телефоните могат да превключват между отделни модули и цифрово изрязване. Провери истинската камера и фокусно разстояние в метаданните, когато геометрията е важна.\n\nКарта за работа — Различавай фокусно разстояние и перспектива\n1. Определи желаната рамка и разстоянието до основния обект.\n2. Избери позиция според отношението на предмета и фона.\n3. Използвай фокусно разстояние, което улавя нужния ъгъл от тази позиция.\n4. Провери лицето/обекта по краищата и при близък план.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv03-10","module":"s02-m03","intro":"Ще отделяш основния предмет от фона с разстояние, светлина и подредба. Ще проверяваш дали детайлът, който доказва твърдението, остава видим.","objective":{"body":"Ще отделяш основния предмет от фона с разстояние, светлина и подредба. Ще проверяваш дали детайлът, който доказва твърдението, остава видим.","deliverable":"Премести кутията от шарен фон към по-чиста повърхност и сравни. Не разчитай на силно размазване, ако то скрива броя на предметите.","check":"Вниманието е върху нужното действие. Фонът остава, когато носи полезен контекст, вместо да бъде премахван по навик."},"note":{"body":"Премести кутията от шарен фон към по-чиста повърхност и сравни. Не разчитай на силно размазване, ако то скрива броя на предметите.\n\nСамопроверка: Вниманието е върху нужното действие. Фонът остава, когато носи полезен контекст, вместо да бъде премахван по навик.\n\nГраница: Субектът не винаги трябва да изпъква силно. В документален кадър фонът може да носи контекст, затова не го махай без причина.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да използваш разстояние, кадриране и светлина за по-ясни планове. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Субектът не винаги трябва да изпъква силно. В документален кадър фонът може да носи контекст, затова не го махай без причина.\n\nКарта за работа — Отдели субекта от фона без софтуерен трик\n1. Определи коя част от субекта трябва да остане четима.\n2. Премести субекта по-напред от фона, ако мястото позволява.\n3. Използвай светлина/цвят/контраст, за да създадеш визуално разделяне.\n4. Провери ръцете, очите и инструмента във финален размер.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата.\n\nДопълнителен теренен тест: Отдалечи фона от героя, приближи камерата и провери контурите; отворената бленда също намалява дълбочината на рязкост, но резултатът зависи от дистанцията и фокусното разстояние."}}},{"lesson":"pv03-11","module":"s02-m03","intro":"Ще знаеш кога ND филтърът помага да запазиш избрани настройки при силна светлина. Ще различаваш намаляване на светлината от поправка на цвят и контраст.","objective":{"body":"Ще знаеш кога ND филтърът помага да запазиш избрани настройки при силна светлина. Ще различаваш намаляване на светлината от поправка на цвят и контраст.","deliverable":"При прекалено ярка сцена сравни преместване на мястото, контрол на светлината и ND, ако вече имаш такъв. Не купувай филтър само за да изпълниш учебния случай.","check":"Избраното средство решава конкретна причина. Не съкращаваш случайно времето на експонация само за да затъмниш кадъра, без да провериш как се променя движението."},"note":{"body":"При прекалено ярка сцена сравни преместване на мястото, контрол на светлината и ND, ако вече имаш такъв. Не купувай филтър само за да изпълниш учебния случай.\n\nСамопроверка: Избраното средство решава конкретна причина. Не съкращаваш случайно времето на експонация само за да затъмниш кадъра, без да провериш как се променя движението.\n\nГраница: ND не намалява динамичния диапазон по същия начин като затваряне на ириса, но евтин филтър може да добави цветен оттенък, отблясък или неравномерност.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да разпознаеш условията, в която неутрално-сив филтър помага да запазиш затвора и диафрагмата. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"ND не намалява динамичния диапазон по същия начин като затваряне на ириса, но евтин филтър може да добави цветен оттенък, отблясък или неравномерност.\n\nКарта за работа — Използвай ND филтър, когато светлината е прекалено силна\n1. Измери яркостта и определи кои настройки искаш да запазиш.\n2. Постави филтър с подходяща плътност и провери цветния неутралитет.\n3. Настрой експозицията отново и тествай неравни/широки повърхности.\n4. Провери винетиране, отражения и кръстосани поляризационни артефакти.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv03-12","module":"s02-m03","intro":"Ще запазваш посоката на действие между свързани кадри. Ще можеш да направиш преход, когато промяната на гледната точка иначе обърква зрителя.","objective":{"body":"Ще запазваш посоката на действие между свързани кадри. Ще можеш да направиш преход, когато промяната на гледната точка иначе обърква зрителя.","deliverable":"Снимай поставянето на предмет от общ план и детайл. Провери дали ръката не сменя необяснимо посоката между тях.","check":"Зрителят може да проследи действието. При пресичане на оста има разбираем преход, не механично спазване на правило."},"note":{"body":"Снимай поставянето на предмет от общ план и детайл. Провери дали ръката не сменя необяснимо посоката между тях.\n\nСамопроверка: Зрителят може да проследи действието. При пресичане на оста има разбираем преход, не механично спазване на правило.\n\nГраница: 180-градусовото правило е ориентир за разбираемост, не забрана. Съзнателното преминаване през оста може да покаже объркване или нова перспектива.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да използваш оста и правилото на 180° за ясна пространствена ориентация. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"180-градусовото правило е ориентир за разбираемост, не забрана. Съзнателното преминаване през оста може да покаже объркване или нова перспектива.\n\nКарта за работа — Пази посоката на действие в монтажа\n1. Определи линията на действие и посоките на поглед/движение.\n2. Постави камерата от едната страна за основните кадри.\n3. Провери посоката в широк, среден и близък план.\n4. Ако пресечеш оста, използвай мотивирано движение или нова опорна гледна точка.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv03-13","module":"s02-m03","intro":"Ще използваш третините като помощ за подредбата, не като оценка за качество. Ще съобразяваш композицията с действието и текста.","objective":{"body":"Ще използваш третините като помощ за подредбата, не като оценка за качество. Ще съобразяваш композицията с действието и текста.","deliverable":"Направи централен и изместен кадър на кутията. Сравни кой оставя място за цената, без да скрива шестте предмета.","check":"Изборът има функция. Кадърът не се отхвърля само защото предметът не стои върху линия от мрежата."},"note":{"body":"Направи централен и изместен кадър на кутията. Сравни кой оставя място за цената, без да скрива шестте предмета.\n\nСамопроверка: Изборът има функция. Кадърът не се отхвърля само защото предметът не стои върху линия от мрежата.\n\nГраница: Нарушаването на третините може да създаде умишлена изолация, официалност или напрежение. Не поправяй композицията само за да съвпада с учебната мрежа.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да разположиш субект и поглед така, че кадърът да подкрепя сцената. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Нарушаването на третините може да създаде умишлена изолация, официалност или напрежение. Не поправяй композицията само за да съвпада с учебната мрежа.\n\nКарта за работа — Използвай третините като насока, не закон\n1. Намери основния обект и важната посока на поглед.\n2. Провери headroom и свободното място пред погледа/движението.\n3. Подреди фон и хоризонт преди да коригираш мрежата.\n4. Сравни третини с централна композиция за задачата.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv03-14","module":"s02-m03","intro":"Ще насочваш погледа с видими линии и форми. Ще разпознаваш елемент, който води вниманието извън нужното действие.","objective":{"body":"Ще насочваш погледа с видими линии и форми. Ще разпознаваш елемент, който води вниманието извън нужното действие.","deliverable":"Премести ръба на масата и яркия предмет на заден план спрямо кутията. Сравни къде погледът се насочва първо.","check":"Линиите подкрепят основния обект. Подредбата не създава риск с кабели, лампи или нестабилни предмети."},"note":{"body":"Премести ръба на масата и яркия предмет на заден план спрямо кутията. Сравни къде погледът се насочва първо.\n\nСамопроверка: Линиите подкрепят основния обект. Подредбата не създава риск с кабели, лампи или нестабилни предмети.\n\nГраница: Формалната линия не оправдава небезопасно разположение на кабел, инструмент или светлина. Подреди сцената след безопасността.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да използваш видимите линии, без да отклоняваш вниманието от главния субект. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Формалната линия не оправдава небезопасно разположение на кабел, инструмент или светлина. Подреди сцената след безопасността.\n\nКарта за работа — Насочи погледа с линии и форми\n1. Определи какво зрителят трябва да види първо.\n2. Огледай реални линии във фона и предния план.\n3. Премести камерата/предмета, за да водят към основното действие.\n4. Провери ръбове за линии, които пресичат лице или изкарват погледа.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv03-15","module":"s02-m03","intro":"Ще оставяш място за надписи, поглед и движение още при снимане. Ще проверяваш текста в реалния предпреглед, а не само върху празна монтажна рамка.","objective":{"body":"Ще оставяш място за надписи, поглед и движение още при снимане. Ще проверяваш текста в реалния предпреглед, а не само върху празна монтажна рамка.","deliverable":"Постави цена и условие за получаване, без да ги наслагваш върху броя на предметите. Прегледай на малък екран при нормална скорост.","check":"Надписът се чете и не е закрит от интерфейса. Цветът служи на йерархията и контраста, не доказва психологически тип."},"note":{"body":"Постави цена и условие за получаване, без да ги наслагваш върху броя на предметите. Прегледай на малък екран при нормална скорост.\n\nСамопроверка: Надписът се чете и не е закрит от интерфейса. Цветът служи на йерархията и контраста, не доказва психологически тип.\n\nГраница: Интерфейсните зони и позицията на субтитрите се различават по платформа. Проверяй конкретната версия, не пренасяй координати сляпо.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да използваш празното пространство така, че да балансира кадъра и да побере нужната информация. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Интерфейсните зони и позицията на субтитрите се различават по платформа. Проверяй конкретната версия, не пренасяй координати сляпо.\n\nКарта за работа — Остави място за поглед и графика\n1. Определи къде ще се поставят субтитри и графика.\n2. Остави място в посоката на поглед или движение.\n3. Провери контраста и чистотата на избраната зона.\n4. Прегледай надпис върху реален кадър и екран.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата.\n\nДопълнителен теренен тест: Планирай празното място по посоката на погледа или движението. Дръж критичния текст извън зоната на бутоните и субтитрите, после прегледай финалния размер на телефона."}}},{"lesson":"pv03-16","module":"s02-m03","intro":"Ще използваш няколко плана за пространство и контекст. Ще различаваш визуална дълбочина от полезност на информацията.","objective":{"body":"Ще използваш няколко плана за пространство и контекст. Ще различаваш визуална дълбочина от полезност на информацията.","deliverable":"Подреди кутия, ръка и фон на различни разстояния. Остави видим точно детайла, който зрителят трябва да разбере.","check":"Всеки слой има причина да присъства. Малката дълбочина на рязкост не скрива ключов предмет или действие."},"note":{"body":"Подреди кутия, ръка и фон на различни разстояния. Остави видим точно детайла, който зрителят трябва да разбере.\n\nСамопроверка: Всеки слой има причина да присъства. Малката дълбочина на рязкост не скрива ключов предмет или действие.\n\nГраница: Дълбочината на рязкост не е равна на дълбочина в историята. Широко отворената бленда може да отнеме контекст, от който зрителят има нужда.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да добавиш дълбочина и контекст, без да претрупаш кадъра. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Дълбочината на рязкост не е равна на дълбочина в историята. Широко отворената бленда може да отнеме контекст, от който зрителят има нужда.\n\nКарта за работа — Използвай преден, среден и заден план\n1. Очерти главния субект и мястото му в сцената.\n2. Добави смислен преден план или остави кадъра чист.\n3. Подреди фон и светлина отделно от героя.\n4. Провери припокриванията и дали всички планове са четими.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv03-17","module":"s02-m03","intro":"Ще избираш движение на камерата с ясна причина и крайна точка. Ще знаеш кога статичният кадър прави демонстрацията по-разбираема.","objective":{"body":"Ще избираш движение на камерата с ясна причина и крайна точка. Ще знаеш кога статичният кадър прави демонстрацията по-разбираема.","deliverable":"Сравни статичен план на шест предмета с плавно приближаване. Избери вариант, в който броят и надписът остават четими.","check":"Движението разкрива информация, а не само украсява. Не ходиш назад с камера без оглед и безопасно осигуряване."},"note":{"body":"Сравни статичен план на шест предмета с плавно приближаване. Избери вариант, в който броят и надписът остават четими.\n\nСамопроверка: Движението разкрива информация, а не само украсява. Не ходиш назад с камера без оглед и безопасно осигуряване.\n\nГраница: Не ходи назад с камера без оператор/осигуряване и оглед на пътя. Плавността не е по-важна от безопасността.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да избираш статичен кадър, панорама, наклон или проследяване според действието. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Не ходи назад с камера без оператор/осигуряване и оглед на пътя. Плавността не е по-важна от безопасността.\n\nКарта за работа — Движи камерата само когато движението помага\n1. Назови защо камерата трябва да се движи в тази сцена.\n2. Маркирай старт, край, траектория и фокус.\n3. Репетирай с актьора/действието и провери препятствията.\n4. Запиши статична алтернатива и сравни кой кадър е по-ясен.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv03-18","module":"s02-m03","intro":"Ще използваш естествена рамка, когато тя добавя смисъл. Ще можеш да отстраниш рамка, която закрива действието или внушава скрито наблюдение.","objective":{"body":"Ще използваш естествена рамка, когато тя добавя смисъл. Ще можеш да отстраниш рамка, която закрива действието или внушава скрито наблюдение.","deliverable":"Пробвай кадър през отворения капак на кутията и обикновен общ план. Сравни дали шестте предмета и ръката се виждат по-добре.","check":"Рамката не скрива доказателството. При реално място не нарушава личния живот и разрешенията за снимане."},"note":{"body":"Пробвай кадър през отворения капак на кутията и обикновен общ план. Сравни дали шестте предмета и ръката се виждат по-добре.\n\nСамопроверка: Рамката не скрива доказателството. При реално място не нарушава личния живот и разрешенията за снимане.\n\nГраница: Не снимай през прозорец/врата, ако това компрометира личния живот или създава нежелано усещане за скрита камера.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да поставиш субекта в естествена рамка, която добавя контекст или фокус. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Не снимай през прозорец/врата, ако това компрометира личния живот или създава нежелано усещане за скрита камера.\n\nКарта за работа — Използвай рамка в рамката с ясна причина\n1. Назови какво дава рамката: контекст, дълбочина или внимание.\n2. Избери естествен елемент и провери безопасност/разрешение.\n3. Премести камерата до чисто разделяне на преден и заден план.\n4. Оцени дали рамката отнема площ или затваря погледа.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv03-19","module":"s02-m03","intro":"Ще избираш визуален баланс според конкретната сцена. Ще различаваш творческо усещане от твърдение, че даден цвят или симетрия влияе еднакво на всички.","objective":{"body":"Ще избираш визуален баланс според конкретната сцена. Ще различаваш творческо усещане от твърдение, че даден цвят или симетрия влияе еднакво на всички.","deliverable":"Сравни централна кутия и кутия с празно място за текст. Избери два цвята с четим контраст и посочи коя информация е най-важна.","check":"Фактите са четими и има ясна йерархия. Не обявяваш палитрата за научно доказан начин да предизвикаш доверие или покупка."},"note":{"body":"Сравни централна кутия и кутия с празно място за текст. Избери два цвята с четим контраст и посочи коя информация е най-важна.\n\nСамопроверка: Фактите са четими и има ясна йерархия. Не обявяваш палитрата за научно доказан начин да предизвикаш доверие или покупка.\n\nГраница: Не обявявай симетрия за „скучна“ или асиметрия за „динамична“ във всеки кадър. Културен контекст, сцена и тон променят прочита.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да сравниш симетричен и асиметричен баланс според намерението. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Не обявявай симетрия за „скучна“ или асиметрия за „динамична“ във всеки кадър. Културен контекст, сцена и тон променят прочита.\n\nКарта за работа — Избери визуален баланс според усещането\n1. Определи основния фокус и желаното усещане.\n2. Огледай големи площи, контрастни точки и движение.\n3. Премести предмети или камера, за да насочиш тежестта.\n4. Сравни кадъра на малък екран и без звук.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}},{"lesson":"pv03-20","module":"s02-m03","intro":"Ще прекадрираш с нова подредба на важните елементи. Ще знаеш кога хоризонтален материал не позволява добра вертикална версия.","objective":{"body":"Ще прекадрираш с нова подредба на важните елементи. Ще знаеш кога хоризонтален материал не позволява добра вертикална версия.","deliverable":"Провери дали кутия, ръка, цена и получаване се побират в 9:16. Ако не се побират, направи отделен детайл или нов дубъл.","check":"Прекрояването запазва нужния факт и посоката на действие. Не предаваш автоматично централно изрязване без преглед."},"note":{"body":"Провери дали кутия, ръка, цена и получаване се побират в 9:16. Ако не се побират, направи отделен детайл или нов дубъл.\n\nСамопроверка: Прекрояването запазва нужния факт и посоката на действие. Не предаваш автоматично централно изрязване без преглед.\n\nГраница: Безопасните зони не са еднакви между Reels, Shorts, Stories и реклами. Използвай актуален предпреглед и правилата за конкретния placement.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да запазиш четимост и визуална йерархия при тесен вертикален кадър. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Безопасните зони не са еднакви между Reels, Shorts, Stories и реклами. Използвай актуален предпреглед и правилата за конкретния placement.\n\nКарта за работа — Прекадрирай композицията за вертикален екран\n1. Избери кое доказателство е най-важно за вертикалната версия.\n2. Премести камерата или направи отделен близък/среден кадър.\n3. Остави чиста зона за субтитри и провери наложения интерфейс.\n4. Гледай експортирания файл в приложението и тествай четливостта.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата.\n\nАктуална справка: Instagram Help — Safe zone for partnership ads: https://help.instagram.com/864398265379023 (провери актуалната версия преди публикуване)."}}},{"lesson":"pv03-21","module":"s02-m03","intro":"Ще събереш завършена последователност и ще провериш самия изнесен файл. Ще различаваш заснет материал, графичен учебен пример и резултат от реална публикация.","objective":{"body":"Ще събереш завършена последователност и ще провериш самия изнесен файл. Ще различаваш заснет материал, графичен учебен пример и резултат от реална публикация.","deliverable":"Предай 25-секундна версия по брифа: собствен запис с шест предмета или обозначена графична версия. Отвори файла и премини новия случай с други условия.","check":"Виждат се брой, цена, получаване и действие. Техническите проверки не удостоверяват творчески вкус, продажби или професионална готовност."},"note":{"body":"Предай 25-секундна версия по брифа: собствен запис с шест предмета или обозначена графична версия. Отвори файла и премини новия случай с други условия.\n\nСамопроверка: Виждат се брой, цена, получаване и действие. Техническите проверки не удостоверяват творчески вкус, продажби или професионална готовност.\n\nГраница: Кадрите в урока са учебен пример, не доказателство за студентски умения. Умението се вижда при реално заснемане и проверка по ясна рубрика; тук автоматичните задачи проверяват решенията, не качеството на подаден файл.\n\nЛист за дубъла: файл и времеви код; ориентация/резолюция; кадри за секунда и затвор; ISO/експозиция; фокус; баланс на бялото; микрофон; дубъл; версия за предаване. Сравни настройките, вместо да разчиташ на памет.\n\nУчебната папка и първият клип са на /academy-labs/perfect-video/start. Можеш да използваш предоставения случай, без да търсиш клиент или оценител."},"before":{"objective":{"body":"да предадеш кратко видео с последователна композиция, проверени настройки и ясна цел. До края ще разпознаеш правилното решение в два случая и ще подредиш работните стъпки."},"field_note":{"body":"Кадрите в урока са учебен пример, не доказателство за студентски умения. Умението се вижда при реално заснемане и проверка по ясна рубрика; тук автоматичните задачи проверяват решенията, не качеството на подаден файл.\n\nЛист за дубъла: файл и времеви код; ориентация/резолюция; кадри за секунда и затвор; ISO/експозиция; фокус; баланс на бялото; микрофон; дубъл; версия за предаване. Сравни настройките, вместо да разчиташ на памет.\n\nКарта за работа — Заснеми последователност, която доказва умението ти\n1. Запиши целта, началното състояние и какъв видим резултат ще доказва процеса.\n2. Сними установяващ, среден, детайлен и завършващ план с посока на действие.\n3. Провери звук, експозиция, фокус, баланс, разрешения и резервно копие.\n4. Монтирай, експортирай и направи финална проверка на телефон.\n\nПреди предаване приложи проверимия резултат: източник, кадър, тестов файл или сценарий според задачата."}}}]$pv_results_payload$::jsonb;
 additions jsonb := $pv_results_additions$[{"lesson":"pv01-01","key":"video_packet_20261003","type":"rich_text","title":"Един проект през първите три модула","content":{"body":"Работи с пекарна „Зърно“ в Лясковец — измислен учебен бизнес. Задачата е 25-секунден клип, който показва кутия с 6 малки банички за 9 € и обяснява вземането от обекта. Наличността се уточнява след запитване. В папката има актуални условия, стара цена, учебни разговори и отчет с ограничения.\n\nОтвори /academy-labs/perfect-video/start. Можеш да започнеш без клиент, покупка, карта или външен AI акаунт. Избираш маршрут: собствен запис с телефон, смесен материал или обозначена графична версия. Графиката не доказва как изглежда истински продукт.\n\nМодул 1 оставя бриф; модул 2 — сценарий и разкадровка; модул 3 — последователност и проверен файл. Не е необходимо да прочетеш всички 65 урока, преди да направиш първата ограничена проба. Върни се към урока, който обяснява конкретния ти пропуск."}},{"lesson":"pv01-02","key":"video_choice_20261003","type":"rich_text","title":"Как човекът решава дали да продължи","content":{"body":"Преди да реши дали да действа, зрителят трябва да разпознае задачата си, да разбере предложението и да прецени важните условия. Това не е еднакъв ред за всеки човек. Проверяваме го чрез конкретни въпроси и поведение, а не чрез етикети за възраст или характер.\n\nВ учебния разговор „Не разбрах дали доставяте“ показва липсваща информация. „Организирам закуска за шестима“ описва ситуация, не готовност за плащане. „Искам да попитам дали ще има за събота“ показва следваща стъпка, не потвърдена поръчка. Клипът трябва да помогне с избраната липса, без да добавя условия, които бизнесът не изпълнява.\n\nПробвай две честни версии: ранно показване на съдържанието и ранно уточняване на получаването. Запиши какво очакваш да се промени и какво наблюдение би опровергало идеята."}},{"lesson":"pv01-04","key":"checkpoint_video_interview_20261003","type":"matching","title":"Наблюдение, предположение и неутрален въпрос","content":{"skillName":"Наблюдение, предположение и неутрален въпрос","body":"Свържи всяка учебна реплика с това, което действително позволява да кажем.","instruction":"Свържи всяка учебна реплика с това, което действително позволява да кажем.","left":[{"id":"neutral","text":"Как организира последната обща закуска?"},{"id":"delivery","text":"Не разбрах дали доставяте."},{"id":"purchase","text":"Щом харесва снимката, ще купи."}],"right":[{"id":"question","text":"Неутрален въпрос за конкретно поведение"},{"id":"observation","text":"Наблюдение за неясно условие"},{"id":"guess","text":"Предположение, което още не е проверено"}]},"evaluation":{"matches":{"neutral":"question","delivery":"observation","purchase":"guess"}},"feedback":{"explanation":"Въпросът не подсказва одобрение. Репликата за доставка показва неяснота; впечатлението от снимка не удостоверява покупка."}},{"lesson":"pv01-12","key":"checkpoint_video_idea_20261003","type":"scenario","title":"Избери изпълнима концепция","content":{"skillName":"Избери изпълнима концепция","prompt":"Имаш телефон, шест предмета и утвърдени условия за 6 броя за 9 €. Няма данни за бъдещи продажби. Коя концепция можеш да изпълниш и провериш?","options":[{"id":"viral","label":"Силен хук с обещание за удвояване на поръчките."},{"id":"show","label":"Покажи броя, цената и получаването; покани за запитване."},{"id":"scarcity","label":"Обяви последни две кутии, за да има причина за бързо решение."}]},"evaluation":{"correct":"show"},"feedback":{"explanation":"Показването изпълнява ограничена задача с наличен материал. Виралността, ръстът и недостигът не са установени факти."}},{"lesson":"pv01-24","key":"checkpoint_video_brief_20261003","type":"matching","title":"Провери брифа срещу условията","content":{"skillName":"Провери брифа срещу условията","body":"Свържи решението за клипа с правилния факт или граница.","instruction":"Свържи решението за клипа с правилния факт или граница.","left":[{"id":"quantity","text":"Какво показва кутията?"},{"id":"price","text":"Коя цена използваш?"},{"id":"pickup","text":"Как се получава?"},{"id":"action","text":"Какво обещава последната стъпка?"}],"right":[{"id":"six","text":"6 малки банички"},{"id":"current","text":"9 € от актуалните условия"},{"id":"shop","text":"Вземане от обекта след уточняване"},{"id":"ask","text":"Запитване, не потвърдена поръчка"}]},"evaluation":{"matches":{"quantity":"six","price":"current","pickup":"shop","action":"ask"}},"feedback":{"explanation":"Старата цена от 8 € и желанието за доставка не променят утвърденото предложение. Наличността остава за уточняване."}},{"lesson":"pv02-03","key":"video_attention_20261003","type":"rich_text","title":"Любопитство, полезност и причина за споделяне","content":{"body":"Хукът е първият образ или реплика, който дава причина да останеш. „Закуска за шестима?“ отваря въпрос, който този клип може да разреши. „Тайната, която пекарните крият“ добавя обвинение без доказателство.\n\nЗа споделяне търси конкретна полза или разпознаваема ситуация: човек може да изпрати клипа на колега, който организира закуска. Това е хипотеза за нашия случай, не гаранция. Изследването на Berger и Milkman от 2012 г. свързва определени емоции и полезност със споделяне в конкретни данни; то не дава формула за всяка платформа или български бизнес. Източник: https://doi.org/10.1509/JMR.10.0353 .\n\nНе оценяваме идея по „допамин“, измислен психологически процент или обещание за вирусен успех. Записваме очаквана реакция, преглеждаме действителния резултат и поправяме версията."}},{"lesson":"pv02-03","key":"checkpoint_video_hook_20261003","type":"matching","title":"Изпълни обещанието на началото","content":{"skillName":"Изпълни обещанието на началото","body":"Свържи началото с това, което видеото трябва да покаже, за да е честно.","instruction":"Свържи началото с това, което видеото трябва да покаже, за да е честно.","left":[{"id":"six","text":"Закуска за шестима?"},{"id":"pickup","text":"Как се получава кутията?"},{"id":"claim","text":"Доставяме безплатно!"}],"right":[{"id":"quantity","text":"Видими шест предмета или ясно обозначена схема"},{"id":"conditions","text":"Вземане от обекта и уточняване на наличността"},{"id":"unsupported","text":"Не използвай: няма такова утвърдено условие"}]},"evaluation":{"matches":{"six":"quantity","pickup":"conditions","claim":"unsupported"}},"feedback":{"explanation":"Началото задава очакване, което останалото видео изпълнява. Непотвърдена доставка не става факт чрез надпис или кадър."}},{"lesson":"pv02-11","key":"video_archetype_20261003","type":"rich_text","title":"Архетипът е творческа роля, не етикет за човек","content":{"body":"В сценария можеш да използваш роля като майстор, водач или закачлив домакин. Тя помага да избереш глас, поведение и вид доказателство. Майсторът показва процес; водачът обяснява стъпка; домакинът свързва продукта с позната ситуация. Това са наши творчески ориентири, не тест за личност.\n\nЮнгианските идеи и по-късните модели за бранд архетипи не са една и съща система. Нямаме основание да преподаваме универсално „цветово колело на Юнг“, което предсказва кога човек ще купи. Ако използваш външен модел, назови точния му автор и предназначение.\n\nЗа „Зърно“ сравни „Ето какво има в кутията“ и „Кой организира съботната закуска?“. Избери тон, който изпълнява задачата. И в двата варианта условията остават 6 броя, 9 €, вземане от обекта и запитване за наличност."}},{"lesson":"pv02-11","key":"checkpoint_video_voice_20261003","type":"scenario","title":"Различен тон, една и съща истина","content":{"skillName":"Различен тон, една и съща истина","prompt":"Избираш гласа на „Зърно“ като спокоен майстор. Как използваш творческата роля?","options":[{"id":"label","label":"Определям всички сини зрители като рационални купувачи."},{"id":"role","label":"Показвам конкретно съдържанието и обяснявам условията с ясни думи."},{"id":"wheel","label":"Избирам цвят от колело и обявявам, че той гарантира доверие."}]},"evaluation":{"correct":"role"},"feedback":{"explanation":"Ролята направлява начина на разказване. Не доказва психологически тип, ефект от цвят или готовност за покупка."}},{"lesson":"pv02-18","key":"video_metrics_20261003","type":"rich_text","title":"Какво измерваш към 3 октомври 2026 г.","content":{"body":"Гледане, продължено гледане, посещение, подходящо запитване и поръчка са различни събития. По текущата документация на YouTube от 24.08.2026 г. гледанията се броят при започване на възпроизвеждане във всички формати. Това не удостоверява, че човекът е разбрал предложението. Източник: https://support.google.com/youtube/answer/12220281?hl=en .\n\nАвтоматично обозначените ключови моменти за задържане имат условия: поне 60 секунди и поне 100 гледания, а отчетът може да не покаже всички моменти. Нашият учебен клип е 25 секунди; не очаквай тази конкретна функция да върне същия отчет. Източник: https://support.google.com/youtube/answer/9314415 .\n\nТаблицата в папката е измислена и не е платформен експорт. Тя упражнява сметка и предпазлив извод. При истински тест запиши текущото определение на показателя, източника, периода, аудиторията и начина на разпространение. Броят съобщения не се нарича автоматично поръчки."}},{"lesson":"pv02-18","key":"checkpoint_video_rate_20261003","type":"calculator","title":"Пресметни дела на подходящите запитвания","content":{"skillName":"Пресметни дела на подходящите запитвания","prompt":"Версия A има 20 подходящи запитвания от 400 посещения за един учебен период. Какъв е делът в проценти? Въведи само числото, без знак %. Това не е процент продажби.","label":"Изчислен резултат","unit":"%"},"evaluation":{"value":5,"tolerance":1e-06},"feedback":{"explanation":"20 ÷ 400 × 100 = 5%. Числителят е подходящо запитване, не поръчка. Малък или несъпоставим отчет не доказва причинен ефект."}},{"lesson":"pv02-20","key":"checkpoint_video_scene_20261003","type":"matching","title":"Свържи сцена, факт и следващо действие","content":{"skillName":"Свържи сцена, факт и следващо действие","body":"Подреди смисловите връзки в сценария, не вкуса на монтажа.","instruction":"Подреди смисловите връзки в сценария, не вкуса на монтажа.","left":[{"id":"count","text":"00:03–00:09: съдържание"},{"id":"price","text":"00:09–00:16: условия"},{"id":"availability","text":"00:16–00:21: граница"},{"id":"cta","text":"00:21–00:25: действие"}],"right":[{"id":"show","text":"Показва 6 броя"},{"id":"nine","text":"Показва 9 € и вземане от обекта"},{"id":"check","text":"Уточнява наличността, без да я гарантира"},{"id":"ask","text":"Кани за запитване"}]},"evaluation":{"matches":{"count":"show","price":"nine","availability":"check","cta":"ask"}},"feedback":{"explanation":"Планът има конкретни времена и проверени условия. Графичният пример обяснява предложението; истински продукт изисква разрешен материал."}},{"lesson":"pv03-02","key":"checkpoint_video_shutter_20261003","type":"calculator","title":"Изчисли времето на експонация","content":{"skillName":"Изчисли времето на експонация","prompt":"При 25 кадъра/секунда един кадър трае 1/25 = 0,04 секунди. При отправна точка 180° какво е времето на експонация в секунди? Въведи десетично число, например с българска запетая.","label":"Изчислен резултат","unit":"секунди"},"evaluation":{"value":0.02,"tolerance":1e-06},"feedback":{"explanation":"Половината от 0,04 е 0,02 секунди = 1/50. Удвоява се знаменателят на дробта, не времето. Тестът за мигане и видът движение остават отделни проверки."}},{"lesson":"pv03-08","key":"checkpoint_video_crop_20261003","type":"scenario","title":"Запази доказателството при вертикален кадър","content":{"skillName":"Запази доказателството при вертикален кадър","prompt":"Хоризонтален кадър показва шест предмета. При централно изрязване за 9:16 два от тях изчезват, а надписът още казва „6“. Какво правиш?","options":[{"id":"crop","label":"Предавам изрязването, защото надписът уточнява броя."},{"id":"reshoot","label":"Подреждам или заснемам отделен вертикален кадър, в който нужният брой се вижда."},{"id":"claim","label":"Намалявам надписа на четири, без да променям офертата."}]},"evaluation":{"correct":"reshoot"},"feedback":{"explanation":"Форматът не трябва да премахва ключовото доказателство или да променя продукта. Нов дубъл или различна подредба е конкретна поправка."}},{"lesson":"pv03-19","key":"video_color_20261003","type":"rich_text","title":"Палитра, четливост и граници на обяснението","content":{"body":"Палитрата е подбран набор от цветове. Тя помага да има ред: фон, основен текст и акцент. Започни от четимост и контекст, а не от твърдение „този цвят кара всички да купуват“.\n\nЗа учебната графика можеш да сравниш кремав фон с тъмен текст и тъмен фон със светъл текст. Цветът не трябва да е единствената разлика между вярно и грешно; добави дума или знак. W3C посочва контраст поне 4,5:1 за обикновен текст и 3:1 за голям текст при съответния критерий. Това е проверка за достъпност, не формула за емоция или продажби. Източник: https://www.w3.org/WAI/WCAG22/Understanding/contrast-minimum.html .\n\nПрегледът на Elliot и Maier от 2014 г. разглежда ефекти на цвета и ограниченията на пренасянето им в реални условия. Не извеждаме универсален купувачески тип от цвят. Източник: https://doi.org/10.1146/annurev-psych-010213-115035 .\n\nПровери надписа на телефон при нормално време на кадъра. Изборът на „красив“ цвят не компенсира дребен текст, лош контраст или скрито условие."}},{"lesson":"pv03-21","key":"checkpoint_video_handoff_20261003","type":"matching","title":"Предаване без фалшиво потвърдени умения","content":{"skillName":"Предаване без фалшиво потвърдени умения","body":"Свържи наличната проверка с това, което тя действително удостоверява.","instruction":"Свържи наличната проверка с това, което тя действително удостоверява.","left":[{"id":"metadata","text":"Размер и продължителност на файла"},{"id":"graphic","text":"Обозначена графична версия"},{"id":"sound","text":"Клип без говор и без музика"},{"id":"publication","text":"Няма данни от реална публикация"}],"right":[{"id":"technical","text":"Само отчетените технически свойства"},{"id":"diagram","text":"Разбираема учебна схема, не заснемане на реален продукт"},{"id":"silent","text":"Няма микрофонен или лицензионен музикален тест"},{"id":"unknown","text":"Не е доказана виралност, поръчка или продажба"}]},"evaluation":{"matches":{"metadata":"technical","graphic":"diagram","sound":"silent","publication":"unknown"}},"feedback":{"explanation":"Предаването описва провереното и непровереното. Автоматичният резултат не се превръща в оценка за творчески вкус, реален бизнес ефект или професионална готовност."}}]$pv_results_additions$::jsonb;
 release_name text := 'perfect_video_results_20261003';
 spec jsonb; addition jsonb; lesson_row public.academy_lessons; version_row public.academy_lesson_versions;
 block_row public.academy_lesson_blocks; key_row academy_private.lesson_block_keys;
 learner_before jsonb; identities_before text; grade_before jsonb; grade_after jsonb;
 old_ids uuid[]; new_id uuid; next_position integer; snapshot jsonb; validation_result jsonb;
 already integer; eligible integer;
 refresh_before text; refresh_definition text;
BEGIN
 LOCK TABLE public.academy_lessons,public.academy_lesson_versions,public.academy_lesson_blocks,
 academy_private.lesson_block_keys,public.academy_lesson_progress,public.academy_lesson_attempts_v2,academy_private.lesson_progress_history,public.pdf_progress,public.profiles,public.academy_access_grants,public.academy_user_badges IN SHARE ROW EXCLUSIVE MODE;
 SELECT count(*) INTO already FROM public.academy_lessons l
 WHERE l.module_id IN ('s02-m01','s02-m02','s02-m03') AND EXISTS(
  SELECT 1 FROM public.academy_lesson_audit a WHERE a.academy_lesson_id=l.id
   AND a.version_id=l.published_version_id AND a.details->>'release'=release_name);
 IF already=65 THEN RETURN; END IF;
 IF already<>0 THEN RAISE EXCEPTION 'Partial video results release; stop and inspect'; END IF;
 SELECT count(*) INTO eligible FROM public.academy_lessons l JOIN public.academy_lesson_versions v ON v.id=l.published_version_id
 WHERE l.module_id IN ('s02-m01','s02-m02','s02-m03') AND l.status='published'
  AND l.published_version_id=l.draft_version_id AND v.change_note='Редакционна версия v4.2: 15 стъпки, 13 задължителни и 2 допълнителни; теренен разбор и два автоматично оценявани сценария.';
 IF eligible=0 THEN RAISE NOTICE 'Video v4.2 base absent; results migration skipped'; RETURN; END IF;
 IF eligible<>65 THEN RAISE EXCEPTION 'Expected 65 video base lessons, found %',eligible; END IF;
 learner_before:=jsonb_build_object('public.academy_lesson_progress',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb)::text)) FROM public.academy_lesson_progress x),'public.academy_lesson_attempts_v2',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb)::text)) FROM public.academy_lesson_attempts_v2 x),'academy_private.lesson_progress_history',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb)::text)) FROM academy_private.lesson_progress_history x),'public.pdf_progress',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb)::text)) FROM public.pdf_progress x),'public.profiles',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb)::text)) FROM public.profiles x),'public.academy_access_grants',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb)::text)) FROM public.academy_access_grants x),'public.academy_user_badges',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb)::text)) FROM public.academy_user_badges x));
 SELECT md5(jsonb_agg(jsonb_build_object('id',l.id,'module',l.module_id,'lesson',l.lesson_id,'status',l.status,'published',l.published_version_id,'draft',l.draft_version_id,'number',v.version_number) ORDER BY l.id)::text)
 INTO identities_before FROM public.academy_lessons l LEFT JOIN public.academy_lesson_versions v ON v.id=l.published_version_id;
 SELECT p.prosrc,pg_get_functiondef(p.oid) INTO refresh_before,refresh_definition
 FROM pg_proc p WHERE p.oid='academy_private.refresh_lesson_progress(uuid,uuid)'::regprocedure;
 IF btrim(refresh_before,E' \t\n\r') IS DISTINCT FROM btrim($pv_refresh_expected$
DECLARE
  p public.academy_lesson_progress;
  required_count integer;
  completed_count integer;
  earned integer;
  score_sum integer;
  max_sum integer;
  percent integer;
  status_text text;
  done_at timestamptz;
BEGIN
  SELECT * INTO p FROM public.academy_lesson_progress
  WHERE user_id=p_user AND academy_lesson_id=p_lesson FOR UPDATE;

  SELECT count(*) FILTER (WHERE required AND block_type NOT IN
           ('prompt_builder','practical_response','reflection','homework','submission')),
         count(*) FILTER (WHERE required AND block_type NOT IN
           ('prompt_builder','practical_response','reflection','homework','submission')
           AND block_key=ANY(p.completed_block_keys)),
         coalesce(sum(points) FILTER (WHERE block_key=ANY(p.completed_block_keys)),0)
    INTO required_count,completed_count,earned
  FROM public.academy_lesson_blocks WHERE version_id=p.version_id;

  SELECT coalesce(sum(score),0),coalesce(sum(max_score),0)
    INTO score_sum,max_sum FROM (
      SELECT DISTINCT ON (block_id) block_id,score,max_score
      FROM public.academy_lesson_attempts_v2
      WHERE user_id=p_user AND academy_lesson_id=p_lesson AND version_id=p.version_id
      ORDER BY block_id,created_at DESC
    ) latest;
  percent:=CASE WHEN max_sum>0 THEN round(100.0*score_sum/max_sum)::integer ELSE NULL END;

  IF required_count>0 AND completed_count=required_count THEN
    done_at:=coalesce(p.completed_at,now());
    status_text:=CASE WHEN percent IS NULL OR percent>=80 THEN 'mastered' ELSE 'practicing' END;
  ELSE
    status_text:='learning'; done_at:=NULL;
  END IF;

  UPDATE public.academy_lesson_progress
  SET xp=earned,score_percent=percent,mastery_status=status_text,
      completed_at=done_at,last_activity_at=now()
  WHERE user_id=p_user AND academy_lesson_id=p_lesson RETURNING * INTO p;

  IF done_at IS NOT NULL THEN
    INSERT INTO public.pdf_progress(user_id,module_id,lesson_id,page_number,total_pages,completed,updated_at)
    SELECT p_user,l.module_id,l.lesson_id,1,1,true,now()
    FROM public.academy_lessons l WHERE l.id=p_lesson
    ON CONFLICT(user_id,module_id,lesson_id)
    DO UPDATE SET completed=true,updated_at=now();
  END IF;

  IF cardinality(p.completed_block_keys)>0 THEN
    INSERT INTO public.academy_user_badges(user_id,badge_key,evidence)
    VALUES(p_user,'first-practice',jsonb_build_object('lessonId',p_lesson)) ON CONFLICT DO NOTHING;
  END IF;
  IF (SELECT coalesce(sum(xp),0) FROM public.academy_lesson_progress WHERE user_id=p_user)>=100 THEN
    INSERT INTO public.academy_user_badges(user_id,badge_key,evidence)
    VALUES(p_user,'xp-100',jsonb_build_object('xp',
      (SELECT sum(xp) FROM public.academy_lesson_progress WHERE user_id=p_user))) ON CONFLICT DO NOTHING;
  END IF;
  IF (SELECT count(*) FROM public.academy_lesson_progress
      WHERE user_id=p_user AND mastery_status='mastered')>=3 THEN
    INSERT INTO public.academy_user_badges(user_id,badge_key,evidence)
    VALUES(p_user,'mastery-3',jsonb_build_object('mastered',
      (SELECT count(*) FROM public.academy_lesson_progress
       WHERE user_id=p_user AND mastery_status='mastered'))) ON CONFLICT DO NOTHING;
  END IF;
  RETURN to_jsonb(p);
END $pv_refresh_expected$,E' \t\n\r') THEN
  RAISE EXCEPTION 'Video progress function drift; stop and inspect';
 END IF;

 FOR spec IN SELECT value FROM jsonb_array_elements(specs) LOOP
  SELECT * INTO STRICT lesson_row FROM public.academy_lessons WHERE module_id=spec->>'module' AND lesson_id=spec->>'lesson' FOR UPDATE;
  SELECT * INTO STRICT version_row FROM public.academy_lesson_versions WHERE id=lesson_row.published_version_id FOR UPDATE;
  IF EXISTS(SELECT 1 FROM jsonb_each(spec->'before') e WHERE NOT EXISTS(
    SELECT 1 FROM public.academy_lesson_blocks b WHERE b.version_id=version_row.id AND b.block_key=e.key AND b.content=e.value))
   OR (SELECT count(*) FROM public.academy_lesson_blocks WHERE version_id=version_row.id)<>15 THEN
   RAISE EXCEPTION 'Video source drift for %',lesson_row.lesson_id;
  END IF;
  SELECT array_agg(b.id ORDER BY b.position),
   jsonb_build_object('version',to_jsonb(version_row),'blocks',jsonb_agg(to_jsonb(b)||jsonb_build_object('evaluation',coalesce(k.answer_key,'{}'),'feedback',coalesce(k.feedback,'{}'),'scoring',coalesce(k.scoring,'{}')) ORDER BY b.position)),
   jsonb_agg(jsonb_build_object('id',b.id,'key',b.block_key,'type',b.block_type,'required',b.required,'points',b.points,'answer',k.answer_key,'scoring',k.scoring,
    'graded_content',CASE WHEN b.block_type IN ('quiz','scenario','sequence_sort','matching','calculator','client_simulation','decision_tree','image_hotspot','course_exam') THEN b.content ELSE NULL END,
    'feedback',CASE WHEN lesson_row.lesson_id='pv03-02' AND b.block_key='knowledge_check' THEN k.feedback-'explanation' ELSE k.feedback END) ORDER BY b.id)
  INTO old_ids,snapshot,grade_before FROM public.academy_lesson_blocks b LEFT JOIN academy_private.lesson_block_keys k ON k.block_id=b.id WHERE b.version_id=version_row.id;
  INSERT INTO public.academy_lesson_audit(academy_lesson_id,version_id,action,details)
  VALUES(lesson_row.id,version_row.id,'saved',jsonb_build_object('release',release_name,'mode','compatible_results_supplement','before',snapshot,'progress_unchanged',true,'new_checks_optional',true)
   || CASE WHEN lesson_row.lesson_id='pv01-01' THEN jsonb_build_object('before_refresh_function',refresh_definition) ELSE '{}'::jsonb END);
  UPDATE public.academy_lesson_blocks SET content=spec->'objective' WHERE version_id=version_row.id AND block_key='objective';
  UPDATE public.academy_lesson_blocks SET content=spec->'note' WHERE version_id=version_row.id AND block_key='field_note';

  IF lesson_row.lesson_id='pv03-02' THEN
   SELECT * INTO STRICT block_row FROM public.academy_lesson_blocks WHERE version_id=version_row.id AND block_key='core';
   IF position('Начална отправна точка е експонация около два пъти по-дълга от кадъра, но това е творческа настройка, не закон.' in block_row.content->>'body')=0 THEN RAISE EXCEPTION 'Shutter source drift'; END IF;
   UPDATE public.academy_lesson_blocks SET content=jsonb_set(content,'{body}',to_jsonb(replace(content->>'body','Начална отправна точка е експонация около два пъти по-дълга от кадъра, но това е творческа настройка, не закон.','При отправна точка 180° времето на експонация е около половината от времето на един кадър: 1/(2 × кадри в секунда). При 25 кадъра/секунда това е 1/50 секунда. Това е творческа отправна точка, не закон и не гаранция срещу мигане.'))) WHERE id=block_row.id;
   SELECT * INTO STRICT block_row FROM public.academy_lesson_blocks WHERE version_id=version_row.id AND block_key='summary';
   IF position('Начална отправна точка е експонация около два пъти по-дълга от кадъра, но това е творческа настройка, не закон.' in block_row.content#>>'{takeaways,0}')=0 THEN RAISE EXCEPTION 'Shutter summary drift'; END IF;
   UPDATE public.academy_lesson_blocks SET content=jsonb_set(content,'{takeaways,0}',to_jsonb(replace(content#>>'{takeaways,0}','Начална отправна точка е експонация около два пъти по-дълга от кадъра, но това е творческа настройка, не закон.','При отправна точка 180° времето на експонация е около половината от времето на един кадър: 1/(2 × кадри в секунда). При 25 кадъра/секунда това е 1/50 секунда. Това е творческа отправна точка, не закон и не гаранция срещу мигане.'))) WHERE id=block_row.id;
   SELECT * INTO STRICT block_row FROM public.academy_lesson_blocks WHERE version_id=version_row.id AND block_key='knowledge_check';
   SELECT * INTO STRICT key_row FROM academy_private.lesson_block_keys WHERE block_id=block_row.id;
   IF position('Начална отправна точка е експонация около два пъти по-дълга от кадъра, но това е творческа настройка, не закон.' in key_row.feedback->>'explanation')=0 THEN RAISE EXCEPTION 'Shutter feedback drift'; END IF;
   UPDATE academy_private.lesson_block_keys SET feedback=jsonb_set(feedback,'{explanation}',to_jsonb(replace(feedback->>'explanation','Начална отправна точка е експонация около два пъти по-дълга от кадъра, но това е творческа настройка, не закон.','При отправна точка 180° времето на експонация е около половината от времето на един кадър: 1/(2 × кадри в секунда). При 25 кадъра/секунда това е 1/50 секунда. Това е творческа отправна точка, не закон и не гаранция срещу мигане.'))) WHERE block_id=block_row.id;
  END IF;

  SELECT coalesce(max(position),0)+1 INTO next_position FROM public.academy_lesson_blocks WHERE version_id=version_row.id;
  FOR addition IN SELECT value FROM jsonb_array_elements(additions) WHERE value->>'lesson'=lesson_row.lesson_id LOOP
   INSERT INTO public.academy_lesson_blocks(version_id,block_key,position,block_type,title,content,required,points)
   VALUES(version_row.id,addition->>'key',next_position,addition->>'type',addition->>'title',addition->'content',false,0) RETURNING id INTO new_id;
   next_position:=next_position+1;
   IF addition?'evaluation' THEN
    INSERT INTO academy_private.lesson_block_keys(block_id,answer_key,feedback,scoring) VALUES(new_id,addition->'evaluation',addition->'feedback','{}');
   END IF;
  END LOOP;
  SELECT jsonb_agg(jsonb_build_object('id',b.id,'key',b.block_key,'type',b.block_type,'required',b.required,'points',b.points,'answer',k.answer_key,'scoring',k.scoring,
   'graded_content',CASE WHEN b.block_type IN ('quiz','scenario','sequence_sort','matching','calculator','client_simulation','decision_tree','image_hotspot','course_exam') THEN b.content ELSE NULL END,
   'feedback',CASE WHEN lesson_row.lesson_id='pv03-02' AND b.block_key='knowledge_check' THEN k.feedback-'explanation' ELSE k.feedback END) ORDER BY b.id)
  INTO grade_after FROM public.academy_lesson_blocks b LEFT JOIN academy_private.lesson_block_keys k ON k.block_id=b.id WHERE b.id=ANY(old_ids);
  IF grade_before IS DISTINCT FROM grade_after THEN RAISE EXCEPTION 'Existing video grading changed for %',lesson_row.lesson_id; END IF;
  IF EXISTS(SELECT 1 FROM public.academy_lesson_blocks WHERE version_id=version_row.id AND NOT(id=ANY(old_ids)) AND (required OR points<>0)) THEN RAISE EXCEPTION 'New activity changed video completion or XP'; END IF;
  validation_result:=academy_private.lesson_validation(version_row.id);
  IF jsonb_array_length(validation_result->'errors')>0 THEN RAISE EXCEPTION 'Invalid video lesson %: %',lesson_row.lesson_id,validation_result; END IF;
  UPDATE public.academy_lesson_versions SET objective=spec->>'intro',change_note=release_name,validation=validation_result WHERE id=version_row.id;
 END LOOP;
 EXECUTE $pv_refresh_definition$CREATE OR REPLACE FUNCTION academy_private.refresh_lesson_progress(p_user uuid, p_lesson uuid)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path TO '' AS $function$
DECLARE
  p public.academy_lesson_progress;
  required_count integer;
  completed_count integer;
  earned integer;
  score_sum integer;
  max_sum integer;
  percent integer;
  status_text text;
  done_at timestamptz;
BEGIN
  SELECT * INTO p FROM public.academy_lesson_progress
  WHERE user_id=p_user AND academy_lesson_id=p_lesson FOR UPDATE;

  -- The new zero-XP checks record attempts and their own completion, not a new
  -- grade, mastery, XP, PDF completion or badge for the old lesson.
  IF EXISTS (
    SELECT 1 FROM public.academy_lessons l
    JOIN public.academy_lesson_blocks b ON b.version_id=l.published_version_id
    WHERE l.id=p_lesson AND l.module_id IN ('s02-m01','s02-m02','s02-m03')
      AND p.version_id=l.published_version_id AND b.block_key=p.current_block_key
      AND b.block_key=ANY(ARRAY['checkpoint_video_interview_20261003','checkpoint_video_idea_20261003','checkpoint_video_brief_20261003','checkpoint_video_hook_20261003','checkpoint_video_voice_20261003','checkpoint_video_rate_20261003','checkpoint_video_scene_20261003','checkpoint_video_shutter_20261003','checkpoint_video_crop_20261003','checkpoint_video_handoff_20261003'])
      AND NOT b.required AND b.points=0
      AND b.block_type IN ('matching','scenario','calculator')
  ) THEN RETURN to_jsonb(p); END IF;

  SELECT count(*) FILTER (WHERE required AND block_type NOT IN
           ('prompt_builder','practical_response','reflection','homework','submission')),
         count(*) FILTER (WHERE required AND block_type NOT IN
           ('prompt_builder','practical_response','reflection','homework','submission')
           AND block_key=ANY(p.completed_block_keys)),
         coalesce(sum(points) FILTER (WHERE block_key=ANY(p.completed_block_keys)),0)
    INTO required_count,completed_count,earned
  FROM public.academy_lesson_blocks WHERE version_id=p.version_id;

  SELECT coalesce(sum(score),0),coalesce(sum(max_score),0)
    INTO score_sum,max_sum FROM (
      SELECT DISTINCT ON (block_id) block_id,score,max_score
      FROM public.academy_lesson_attempts_v2
      WHERE user_id=p_user AND academy_lesson_id=p_lesson AND version_id=p.version_id
      ORDER BY block_id,created_at DESC
    ) latest;
  percent:=CASE WHEN max_sum>0 THEN round(100.0*score_sum/max_sum)::integer ELSE NULL END;

  IF required_count>0 AND completed_count=required_count THEN
    done_at:=coalesce(p.completed_at,now());
    status_text:=CASE WHEN percent IS NULL OR percent>=80 THEN 'mastered' ELSE 'practicing' END;
  ELSE
    status_text:='learning'; done_at:=NULL;
  END IF;

  UPDATE public.academy_lesson_progress
  SET xp=earned,score_percent=percent,mastery_status=status_text,
      completed_at=done_at,last_activity_at=now()
  WHERE user_id=p_user AND academy_lesson_id=p_lesson RETURNING * INTO p;

  IF done_at IS NOT NULL THEN
    INSERT INTO public.pdf_progress(user_id,module_id,lesson_id,page_number,total_pages,completed,updated_at)
    SELECT p_user,l.module_id,l.lesson_id,1,1,true,now()
    FROM public.academy_lessons l WHERE l.id=p_lesson
    ON CONFLICT(user_id,module_id,lesson_id)
    DO UPDATE SET completed=true,updated_at=now();
  END IF;

  IF cardinality(p.completed_block_keys)>0 THEN
    INSERT INTO public.academy_user_badges(user_id,badge_key,evidence)
    VALUES(p_user,'first-practice',jsonb_build_object('lessonId',p_lesson)) ON CONFLICT DO NOTHING;
  END IF;
  IF (SELECT coalesce(sum(xp),0) FROM public.academy_lesson_progress WHERE user_id=p_user)>=100 THEN
    INSERT INTO public.academy_user_badges(user_id,badge_key,evidence)
    VALUES(p_user,'xp-100',jsonb_build_object('xp',
      (SELECT sum(xp) FROM public.academy_lesson_progress WHERE user_id=p_user))) ON CONFLICT DO NOTHING;
  END IF;
  IF (SELECT count(*) FROM public.academy_lesson_progress
      WHERE user_id=p_user AND mastery_status='mastered')>=3 THEN
    INSERT INTO public.academy_user_badges(user_id,badge_key,evidence)
    VALUES(p_user,'mastery-3',jsonb_build_object('mastered',
      (SELECT count(*) FROM public.academy_lesson_progress
       WHERE user_id=p_user AND mastery_status='mastered'))) ON CONFLICT DO NOTHING;
  END IF;
  RETURN to_jsonb(p);
END $function$;$pv_refresh_definition$;

 IF learner_before IS DISTINCT FROM jsonb_build_object('public.academy_lesson_progress',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb)::text)) FROM public.academy_lesson_progress x),'public.academy_lesson_attempts_v2',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb)::text)) FROM public.academy_lesson_attempts_v2 x),'academy_private.lesson_progress_history',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb)::text)) FROM academy_private.lesson_progress_history x),'public.pdf_progress',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb)::text)) FROM public.pdf_progress x),'public.profiles',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb)::text)) FROM public.profiles x),'public.academy_access_grants',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb)::text)) FROM public.academy_access_grants x),'public.academy_user_badges',(SELECT jsonb_build_object('rows',count(*),'hash',md5(coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]'::jsonb)::text)) FROM public.academy_user_badges x)) THEN RAISE EXCEPTION 'Learner records changed; abort video results release'; END IF;
 IF identities_before IS DISTINCT FROM (SELECT md5(jsonb_agg(jsonb_build_object('id',l.id,'module',l.module_id,'lesson',l.lesson_id,'status',l.status,'published',l.published_version_id,'draft',l.draft_version_id,'number',v.version_number) ORDER BY l.id)::text) FROM public.academy_lessons l LEFT JOIN public.academy_lesson_versions v ON v.id=l.published_version_id) THEN RAISE EXCEPTION 'Published lesson identity changed'; END IF;
 IF (SELECT count(*) FROM public.academy_lesson_blocks b JOIN public.academy_lessons l ON l.published_version_id=b.version_id WHERE l.module_id IN ('s02-m01','s02-m02','s02-m03') AND b.block_key LIKE 'checkpoint_video_%_20261003')<>10 THEN RAISE EXCEPTION 'Missing video checkpoints'; END IF;
 UPDATE public.academy_lesson_audit SET details=details||jsonb_build_object('publication_receipt',jsonb_build_object('release',release_name,'published_lessons',65,'optional_blocks',jsonb_array_length(additions),'independent_checks',10,'applied_at',clock_timestamp(),'learner_records_unchanged',true,'lesson_identity_unchanged',true,'correct_answers_unchanged',true,'checked_tables',learner_before))
 WHERE version_id=(SELECT published_version_id FROM public.academy_lessons WHERE module_id='s02-m01' AND lesson_id='pv01-01') AND details->>'release'=release_name;
END $video_results$;
